window.DATA = {"i18n": {"site_title": {"az": "AN Psixoloji Mərkəzi — Diaqnostik Qiymətləndirmə", "ru": "AN Психологический Центр — Диагностическая оценка", "en": "AN Psychology Center — Diagnostic Assessment"}, "nav_home": {"az": "Ana səhifə", "ru": "Главная", "en": "Home"}, "brand": {"az": "AN Psixoloji Mərkəzi", "ru": "AN Психологический Центр", "en": "AN Psychology Center"}, "center_full": {"az": "AN Psixoloji Dəstək və Reabilitasiya Mərkəzi", "ru": "AN Центр психологической поддержки и реабилитации", "en": "AN Center for Psychological Support and Rehabilitation"}, "hero_eyebrow": {"az": "Diplomlu və sertifikatlı mütəxəssislər tərəfindən", "ru": "Дипломированные и сертифицированные специалисты", "en": "By qualified and certified specialists"}, "hero_title_a": {"az": "Xüsusi qayğıya ehtiyacı olan uşaqlar üçün", "ru": "Для детей с особыми потребностями —", "en": "For children with special needs —"}, "hero_title_em": {"az": "diaqnostik qiymətləndirmə", "ru": "диагностическая оценка", "en": "diagnostic assessment"}, "hero_title_b": {"az": "sistemi", "ru": "система", "en": "system"}, "hero_lead": {"az": "Altı beynəlxalq qiymətləndirmə aləti bir platformada. Mərkəzimizin mütəxəssisləri uşağı qiymətləndirir, sistem isə müşahidələri toplayır, peşəkar hesabat hazırlayır və həm mütəxəssisə, həm valideynə aydın tövsiyələr verir.", "ru": "Шесть международных инструментов оценки на одной платформе. Специалисты нашего центра оценивают ребёнка, а система собирает наблюдения, формирует профессиональный отчёт и даёт понятные рекомендации специалисту и родителю.", "en": "Six international assessment tools on one platform. Our specialists assess the child, while the system collects observations, builds a professional report and gives clear recommendations to both specialist and parent."}, "stat_tools": {"az": "Qiymətləndirmə aləti", "ru": "Инструментов оценки", "en": "Assessment tools"}, "stat_cert": {"az": "Sertifikatlı mütəxəssis", "ru": "Сертифицированные специалисты", "en": "Certified specialists"}, "stat_report": {"az": "Mütəxəssis + valideyn hesabatı", "ru": "Отчёт для специалиста и родителя", "en": "Specialist + parent report"}, "scroll": {"az": "Aşağı", "ru": "Вниз", "en": "Scroll"}, "tools_kicker": {"az": "Qiymətləndirmə alətləri", "ru": "Инструменты оценки", "en": "Assessment tools"}, "tools_head": {"az": "Mərkəzimizdə keçirilən testlər", "ru": "Тесты, проводимые в нашем центре", "en": "Tests conducted at our center"}, "tools_sub": {"az": "Hər test ayrı bölmədə açılır: yuxarıda keçirilmə təlimatı, sonra uşaq və mütəxəssis məlumatları, müşahidə sahələri və nəticə hesabatı.", "ru": "Каждый тест открывается в отдельном разделе: инструкция по проведению, данные ребёнка и специалиста, области наблюдения и итоговый отчёт.", "en": "Each test opens in its own section: administration guide, child and specialist details, observation areas and a final report."}, "why_kicker": {"az": "Niyə bizim mərkəz", "ru": "Почему наш центр", "en": "Why our center"}, "why_head": {"az": "Bu yanaşmanın üstünlükləri", "ru": "Преимущества подхода", "en": "Advantages of this approach"}, "prof_note": {"az": "Peşəkar qeyd.", "ru": "Профессиональное примечание.", "en": "Professional note."}, "prof_note_txt": {"az": "Bu platforma standartlaşdırılmış testləri əvəz etmir — onları dəstəkləyir. Yekun bal, norma müqayisəsi və diaqnoz həmişə mərkəzin rəsmi, lisenziyalı dəsti və ixtisaslı mütəxəssisin mühakiməsi ilə müəyyən edilir. Sistemin müşahidə xülasələri qərar dəstəyi məqsədi daşıyır.", "ru": "Эта платформа не заменяет стандартизированные тесты — она их дополняет. Итоговый балл, сравнение с нормами и диагноз всегда определяются официальным лицензированным набором центра и суждением квалифицированного специалиста. Сводки наблюдений служат поддержкой решения.", "en": "This platform does not replace standardized tests — it supports them. The final score, norm comparison and diagnosis are always determined by the center's official licensed kit and the judgment of a qualified specialist. The observation summaries are intended as decision support."}, "open_test": {"az": "Testi aç", "ru": "Открыть тест", "en": "Open test"}, "areas": {"az": "sahə", "ru": "обл.", "en": "areas"}, "back": {"az": "Geri", "ru": "Назад", "en": "Back"}, "howto": {"az": "Keçirilmə qaydası", "ru": "Порядок проведения", "en": "Administration"}, "methods": {"az": "Forma və metodlar", "ru": "Формы и методы", "en": "Forms & methods"}, "scoring": {"az": "Qiymətləndirmə və yekun", "ru": "Оценка и итог", "en": "Scoring & summary"}, "child_info": {"az": "Uşaq haqqında məlumat", "ru": "Данные о ребёнке", "en": "Child information"}, "spec_info": {"az": "Mütəxəssis haqqında", "ru": "О специалисте", "en": "Specialist information"}, "f_name": {"az": "Uşağın adı", "ru": "Имя ребёнка", "en": "Child's first name"}, "f_surname": {"az": "Uşağın soyadı", "ru": "Фамилия ребёнка", "en": "Child's surname"}, "f_age": {"az": "Yaş", "ru": "Возраст", "en": "Age"}, "f_spec_name": {"az": "Mütəxəssisin adı", "ru": "Имя специалиста", "en": "Specialist's first name"}, "f_spec_surname": {"az": "Mütəxəssisin soyadı", "ru": "Фамилия специалиста", "en": "Specialist's surname"}, "f_profession": {"az": "Peşə", "ru": "Профессия", "en": "Profession"}, "f_wa": {"az": "Valideynin WhatsApp nömrəsi (göndərmək üçün)", "ru": "WhatsApp родителя (для отправки)", "en": "Parent's WhatsApp number (to send)"}, "f_wa_ph": {"az": "məs. 994501234567 (ölkə kodu ilə)", "ru": "напр. 994501234567 (с кодом страны)", "en": "e.g. 994501234567 (with country code)"}, "official_kicker": {"az": "Rəsmi bal (istəyə bağlı)", "ru": "Официальный балл (по желанию)", "en": "Official score (optional)"}, "official_note": {"az": "Bu bölmə məcburi deyil. Lisenziyalı dəstdən rəsmi bal almısınızsa, onu buraya əlavə edin, hesabata daxil olacaq. Bu ballar nəticənin hesablanmasına təsir etmir, hesabatda yalnız göstərilir. Boş buraxsanız, hesabat yalnız müşahidələrə əsaslanacaq.", "ru": "Этот раздел необязателен. Если вы получили официальный балл по лицензированному набору, добавьте его здесь, и он попадёт в отчёт. Эти баллы не влияют на расчёт результата и лишь отображаются в отчёте. Если оставить пустым, отчёт будет основан только на наблюдениях.", "en": "This section is optional. If you have an official score from the licensed kit, add it here and it will be included in the report. These scores do not affect how the result is calculated and are only displayed in the report. If left empty, the report will rely on observations only."}, "obs_kicker": {"az": "Müşahidə sahələri", "ru": "Области наблюдения", "en": "Observation areas"}, "obs_note": {"az": "Hər bənd üzrə müşahidənizi qeyd edin. Bu, rəsmi balı əvəz etmir — onu tamamlayır.", "ru": "Отметьте ваше наблюдение по каждому пункту. Это не заменяет официальный балл, а дополняет его.", "en": "Mark your observation for each item. This does not replace the official score — it complements it."}, "show_result": {"az": "Nəticəni göstər", "ru": "Показать результат", "en": "Show result"}, "progress": {"az": "tamamlandı", "ru": "заполнено", "en": "completed"}, "result_title": {"az": "Qiymətləndirmə hesabatı", "ru": "Отчёт об оценке", "en": "Assessment report"}, "res_official": {"az": "Daxil edilmiş rəsmi ballar", "ru": "Введённые официальные баллы", "en": "Entered official scores"}, "res_domains": {"az": "Müşahidə xülasəsi (sahələr üzrə)", "ru": "Сводка наблюдений (по областям)", "en": "Observation summary (by area)"}, "res_diag": {"az": "Mütəxəssis üçün diaqnostik mülahizələr", "ru": "Диагностические соображения для специалиста", "en": "Diagnostic considerations for the specialist"}, "res_spec": {"az": "Mütəxəssisə tövsiyələr", "ru": "Рекомендации специалисту", "en": "Recommendations for the specialist"}, "res_parent": {"az": "Valideynə sadə dildə tövsiyələr", "ru": "Простые рекомендации для родителя", "en": "Simple recommendations for the parent"}, "res_games": {"az": "Evdə oyun nümunələri", "ru": "Примеры игр дома", "en": "Example games at home"}, "send_wa": {"az": "WhatsApp-a göndər", "ru": "Отправить в WhatsApp", "en": "Send to WhatsApp"}, "save_report": {"az": "Hesabatı yüklə (HTML)", "ru": "Скачать отчёт (HTML)", "en": "Download report (HTML)"}, "print_pdf": {"az": "Çap / PDF", "ru": "Печать / PDF", "en": "Print / PDF"}, "edit_again": {"az": "Yenidən redaktə et", "ru": "Редактировать снова", "en": "Edit again"}, "fill_more": {"az": "Hesabat üçün daha çox sahəni doldurun.", "ru": "Заполните больше областей для отчёта.", "en": "Fill in more areas for the report."}, "band_ok": {"az": "Çətinlik müşahidə olunmur", "ru": "Трудности не наблюдаются", "en": "No difficulty observed"}, "band_warn": {"az": "Yüngül çətinlik", "ru": "Лёгкие трудности", "en": "Mild difficulty"}, "band_high": {"az": "Orta çətinlik", "ru": "Умеренные трудности", "en": "Moderate difficulty"}, "band_crit": {"az": "Əhəmiyyətli çətinlik", "ru": "Значительные трудности", "en": "Significant difficulty"}, "disclaimer": {"az": "Yekun diaqnoz və bal lisenziyalı dəst və ixtisaslı mütəxəssis tərəfindən müəyyən edilir. Bu hesabat qərar dəstəyi məqsədi daşıyır.", "ru": "Итоговый диагноз и балл определяются лицензированным набором и квалифицированным специалистом. Этот отчёт служит поддержкой решения.", "en": "The final diagnosis and score are determined by a licensed kit and a qualified specialist. This report is intended as decision support."}, "foot_rights": {"az": "müvafiq naşirlərin qeydiyyatdan keçmiş alətləridir; rəsmi keçirilmə yalnız lisenziyalı dəst və ixtisaslı mütəxəssis tərəfindən aparılır.", "ru": "являются зарегистрированными инструментами соответствующих издателей; официальное проведение осуществляется только лицензированным набором и квалифицированным специалистом.", "en": "are registered instruments of their respective publishers; official administration is carried out only with a licensed kit and a qualified specialist."}, "contact": {"az": "Əlaqə", "ru": "Контакты", "en": "Contact"}, "address": {"az": "Rizvan Teymurov 59, Bakı", "ru": "Ризван Теймуров 59, Баку", "en": "Rizvan Teymurov 59, Baku"}}, "professions": [{"az": "Klinik psixoloq", "ru": "Клинический психолог", "en": "Clinical psychologist"}, {"az": "Psixoloq", "ru": "Психолог", "en": "Psychologist"}, {"az": "Loqoped", "ru": "Логопед", "en": "Speech therapist"}, {"az": "Erqoterapevt", "ru": "Эрготерапевт", "en": "Occupational therapist"}, {"az": "Defektoloq", "ru": "Дефектолог", "en": "Special educator"}, {"az": "Psixiatr", "ru": "Психиатр", "en": "Psychiatrist"}, {"az": "Reabilitoloq", "ru": "Реабилитолог", "en": "Rehabilitation specialist"}, {"az": "ABA terapevti", "ru": "ABA-терапевт", "en": "ABA therapist"}], "scale": [{"az": "Çətinlik yoxdur", "ru": "Нет трудностей", "en": "No difficulty"}, {"az": "Yüngül", "ru": "Лёгкие", "en": "Mild"}, {"az": "Orta", "ru": "Умеренные", "en": "Moderate"}, {"az": "Əhəmiyyətli", "ru": "Значительные", "en": "Significant"}], "why": [{"icon": "shield", "t": {"az": "Standartı pozmadan", "ru": "Без нарушения стандарта", "en": "Without breaking the standard"}, "d": {"az": "Sistem rəsmi testləri əvəz etmir — mütəxəssisin müşahidələrini sistemli toplayır və qanuni qalır.", "ru": "Система не заменяет официальные тесты — она систематизирует наблюдения специалиста и остаётся легальной.", "en": "The system does not replace official tests — it organizes the specialist's observations and stays legal."}}, {"icon": "report", "t": {"az": "İki hesabat birində", "ru": "Два отчёта в одном", "en": "Two reports in one"}, "d": {"az": "Həm mütəxəssis üçün diaqnostik mülahizələr, həm valideyn üçün sadə dildə tövsiyələr.", "ru": "И диагностические соображения для специалиста, и простые рекомендации для родителя.", "en": "Both diagnostic considerations for the specialist and simple guidance for the parent."}}, {"icon": "clock", "t": {"az": "Vaxta qənaət", "ru": "Экономия времени", "en": "Saves time"}, "d": {"az": "Müşahidələr avtomatik xülasələnir, hesabat dərhal hazır olur.", "ru": "Наблюдения автоматически сводятся, отчёт готов мгновенно.", "en": "Observations are summarized automatically; the report is ready instantly."}}, {"icon": "share", "t": {"az": "Asan paylaşım", "ru": "Простой обмен", "en": "Easy sharing"}, "d": {"az": "Hesabatı WhatsApp ilə göndərin, HTML yükləyin və ya PDF çap edin.", "ru": "Отправьте отчёт в WhatsApp, скачайте HTML или распечатайте в PDF.", "en": "Send the report via WhatsApp, download HTML or print to PDF."}}, {"icon": "globe", "t": {"az": "Üç dildə", "ru": "На трёх языках", "en": "Three languages"}, "d": {"az": "Bütün interfeys və hesabatlar Azərbaycan, rus və ingilis dillərində.", "ru": "Весь интерфейс и отчёты на азербайджанском, русском и английском.", "en": "The entire interface and reports in Azerbaijani, Russian and English."}}, {"icon": "heart", "t": {"az": "Uşaq mərkəzli", "ru": "Ориентир на ребёнка", "en": "Child-centered"}, "d": {"az": "Hər tövsiyə uşağın gündəlik həyatına və ailəsinə real fayda verməyə yönəlib.", "ru": "Каждая рекомендация направлена на реальную пользу для повседневной жизни ребёнка и семьи.", "en": "Every recommendation aims at real benefit for the child's daily life and family."}}], "tests": {"ados2": {"id": "ados2", "name": "ADOS-2", "full": {"az": "Otizm Diaqnostik Müşahidə Cədvəli, 2-ci nəşr", "ru": "План диагностического наблюдения аутизма, 2-е изд.", "en": "Autism Diagnostic Observation Schedule, 2nd ed."}, "age": {"az": "12 aylıqdan böyüklərə qədər (modullar üzrə)", "ru": "от 12 месяцев до взрослых (по модулям)", "en": "12 months to adult (by modules)"}, "summary": {"az": "Sosial ünsiyyət, qarşılıqlı təsir və oyunun strukturlaşdırılmış müşahidəsi. Otizm spektri əlamətlərinin qiymətləndirilməsində istinad alətidir.", "ru": "Структурированное наблюдение социальной коммуникации, взаимодействия и игры. Эталонный инструмент при оценке признаков аутистического спектра.", "en": "Structured observation of social communication, interaction and play. A reference tool in assessing autism spectrum signs."}, "advantages": [{"az": "Birbaşa müşahidəyə əsaslanır", "ru": "Основан на прямом наблюдении", "en": "Based on direct observation"}, {"az": "Yaşa və nitqə görə modulları var", "ru": "Имеет модули по возрасту и речи", "en": "Has modules by age and speech"}, {"az": "Oyun və qarşılıqlı təsir vasitəsilə təbii davranışı açır", "ru": "Раскрывает естественное поведение через игру и взаимодействие", "en": "Reveals natural behavior through play and interaction"}, {"az": "Komanda qərarı üçün güclü dayaq", "ru": "Прочная опора для командного решения", "en": "Strong support for team decision-making"}], "instruction": {"howto": [{"az": "Sakit, az qıcıqlandırıcı otaqda, uşaqla təkbətək keçirin.", "ru": "Проводите наедине с ребёнком в тихой комнате с малым числом раздражителей.", "en": "Conduct one-on-one in a quiet, low-distraction room."}, {"az": "Uşağın yaşına və nitq səviyyəsinə uyğun modulu seçin.", "ru": "Выберите модуль, соответствующий возрасту и уровню речи ребёнка.", "en": "Select the module matching the child's age and speech level."}, {"az": "Təqdim olunan oyun və tapşırıqlar zamanı təbii davranışı müşahidə edin.", "ru": "Наблюдайте естественное поведение во время предложенных игр и заданий.", "en": "Observe natural behavior during the presented games and tasks."}], "methods": [{"az": "Strukturlaşdırılmış oyun və sosial 'tələlər'", "ru": "Структурированная игра и социальные «пробы»", "en": "Structured play and social 'presses'"}, {"az": "Yarımstrukturlaşdırılmış söhbət (nitqi olanlar üçün)", "ru": "Полуструктурированная беседа (для говорящих)", "en": "Semi-structured conversation (for verbal children)"}, {"az": "Birgə fəaliyyət və müşahidə", "ru": "Совместная деятельность и наблюдение", "en": "Joint activity and observation"}], "scoring": [{"az": "Müşahidə kodları sosial təsir və ünsiyyət üzrə alqoritmə yığılır.", "ru": "Коды наблюдения сводятся в алгоритм по взаимодействию и коммуникации.", "en": "Observation codes feed an algorithm for interaction and communication."}, {"az": "Yekun kəsim balı yalnız rəsmi protokol üzrə hesablanır.", "ru": "Итоговый пороговый балл рассчитывается только по официальному протоколу.", "en": "The final cutoff score is computed only per the official protocol."}]}, "official": [{"label": {"az": "Sosial təsir (SA) balı", "ru": "Балл соц. взаимодействия (SA)", "en": "Social Affect (SA) score"}, "hint": {"az": "rəsmi protokoldan", "ru": "из официального протокола", "en": "from official protocol"}}, {"label": {"az": "Məhdud/təkrarlanan (RRB) balı", "ru": "Балл огранич./повтор. (RRB)", "en": "Restricted/Repetitive (RRB) score"}, "hint": {"az": "rəsmi protokoldan", "ru": "из официального протокола", "en": "from official protocol"}}, {"label": {"az": "Ümumi müqayisə balı (CSS)", "ru": "Сравнительный балл (CSS)", "en": "Comparison score (CSS)"}, "hint": {"az": "1–10", "ru": "1–10", "en": "1–10"}}, {"label": {"az": "Modul", "ru": "Модуль", "en": "Module"}, "hint": {"az": "məs. Modul 2", "ru": "напр. Модуль 2", "en": "e.g. Module 2"}}], "domains": [{"id": "d1", "title": {"az": "Göz təması və baxışla tənzimləmə", "ru": "Зрительный контакт и регуляция взглядом", "en": "Eye Contact and Gaze Regulation"}, "task": {"az": "Birgə oyun və söhbət zamanı (oyuncaqlar, baloncuk üfürmə) uşağın baxışına baxılır.", "ru": "Наблюдают за взглядом ребёнка во время совместной игры и беседы (игрушки, мыльные пузыри).", "en": "The child's gaze is observed during joint play and conversation (toys, bubble blowing)."}, "items": [{"id": "d1i1", "t": {"az": "Ünsiyyət zamanı göz təması qurmaqda və saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с установлением и поддержанием зрительного контакта при общении", "en": "Has difficulty establishing and maintaining eye contact during interaction"}}, {"id": "d1i2", "t": {"az": "Baxışı diqqəti yönəltmək üçün istifadə etməkdə çətinlik çəkir (məsələn, istədiyi şeyə baxıb sonra sizə baxmır)", "ru": "Испытывает трудности с использованием взгляда для направления внимания (например, смотрит на желаемое, но не переводит взгляд на вас)", "en": "Has difficulty using gaze to direct attention (for example, looks at the desired object but does not look back at you)"}}, {"id": "d1i3", "t": {"az": "Göz təmasını jest və ya nitqlə uyğunlaşdırmaqda çətinlik çəkir", "ru": "Испытывает трудности с согласованием зрительного контакта с жестами или речью", "en": "Has difficulty coordinating eye contact with gestures or speech"}}]}, {"id": "d2", "title": {"az": "Jest və işarələrdən istifadə", "ru": "Использование жестов", "en": "Use of Gestures"}, "task": {"az": "Uşağın əli çatmayan yerdə maraqlı oyuncaq və ya qab göstərilir, istəyini necə bildirdiyinə baxılır.", "ru": "Интересную игрушку или контейнер показывают так, чтобы ребёнок не мог до них дотянуться, и наблюдают, как он выражает желание.", "en": "An interesting toy or container is placed out of the child's reach and the examiner observes how the child expresses a wish."}, "items": [{"id": "d2i1", "t": {"az": "İstədiyini barmağı ilə göstərməkdə çətinlik çəkir", "ru": "Испытывает трудности с указанием на желаемое пальцем", "en": "Has difficulty pointing to what he or she wants"}}, {"id": "d2i2", "t": {"az": "Baş yelləmə, əl yellətmə kimi mənalı jestlərdən istifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с использованием значимых жестов, таких как кивок или помахивание рукой", "en": "Has difficulty using meaningful gestures such as nodding or waving"}}, {"id": "d2i3", "t": {"az": "Jesti söz və baxışla birləşdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с сочетанием жеста со словом и взглядом", "en": "Has difficulty combining a gesture with words and gaze"}}]}, {"id": "d3", "title": {"az": "Mimika və emosional ifadə", "ru": "Мимика и эмоциональное выражение", "en": "Facial Expressions and Emotional Expression"}, "task": {"az": "Oyun və gözlənilməz hadisələr zamanı (oyuncağın səs çıxarması, balonun partlaması) uşağın üz ifadəsinə baxılır.", "ru": "Наблюдают за выражением лица ребёнка во время игры и неожиданных событий (игрушка издаёт звук, лопается шарик).", "en": "The child's facial expression is observed during play and unexpected events (a toy makes a sound, a balloon pops)."}, "items": [{"id": "d3i1", "t": {"az": "Üz ifadəsi vəziyyətə uyğun gəlmir", "ru": "Выражение лица не соответствует ситуации", "en": "Facial expression does not match the situation"}}, {"id": "d3i2", "t": {"az": "Hisslərini başqasına yönəltməkdə çətinlik çəkir (məsələn, sevincini sizə baxıb göstərmir)", "ru": "Испытывает трудности с адресацией своих чувств другому человеку (например, радуясь, не смотрит на вас)", "en": "Has difficulty directing his or her feelings to another person (for example, does not look at you when happy)"}}, {"id": "d3i3", "t": {"az": "Qarşısındakının ifadəsinə uyğun reaksiya verməkdə çətinlik çəkir", "ru": "Испытывает трудности с адекватной реакцией на выражение лица собеседника", "en": "Has difficulty responding appropriately to the other person's facial expression"}}]}, {"id": "d4", "title": {"az": "Birgə diqqət — cavab", "ru": "Совместное внимание: отклик", "en": "Joint Attention: Response"}, "task": {"az": "Mütəxəssis uzaqdakı oyuncağa baxır və ona barmağı ilə işarə edir, uşağın reaksiyasına baxılır.", "ru": "Специалист смотрит на далёкую игрушку и указывает на неё пальцем, наблюдают за реакцией ребёнка.", "en": "The examiner looks at a distant toy and points to it, and the child's response is observed."}, "items": [{"id": "d4i1", "t": {"az": "Başqasının baxışını və ya işarəsini izləməkdə çətinlik çəkir", "ru": "Испытывает трудности с прослеживанием взгляда или указательного жеста другого человека", "en": "Has difficulty following another person's gaze or pointing gesture"}}, {"id": "d4i2", "t": {"az": "Göstərilən əşyaya diqqətini yönəltməkdə çətinlik çəkir", "ru": "Испытывает трудности с направлением внимания на указанный предмет", "en": "Has difficulty directing attention to the indicated object"}}, {"id": "d4i3", "t": {"az": "Diqqəti paylaşmaq üçün geri baxmaqda çətinlik çəkir", "ru": "Испытывает трудности с обратным взглядом на партнёра для разделения внимания", "en": "Has difficulty looking back at the partner to share attention"}}]}, {"id": "d5", "title": {"az": "Birgə diqqət — təşəbbüs", "ru": "Совместное внимание: инициация", "en": "Joint Attention: Initiation"}, "task": {"az": "Uşağın özü maraqlı bir şey tapanda (səs çıxaran oyuncaq, uçan baloncuk) nə etdiyinə baxılır.", "ru": "Наблюдают за действиями ребёнка, когда он сам находит что-то интересное (звучащая игрушка, летящий пузырь).", "en": "The examiner observes what the child does on finding something interesting (a noisy toy, a floating bubble)."}, "items": [{"id": "d5i1", "t": {"az": "Maraqlı şeyi göstərmək üçün özü təşəbbüs etməkdə çətinlik çəkir", "ru": "Испытывает трудности с самостоятельной инициативой показать интересный предмет", "en": "Has difficulty taking the initiative to show an interesting object"}}, {"id": "d5i2", "t": {"az": "Paylaşmaq üçün əşyanı gətirməkdə və ya uzatmaqda çətinlik çəkir", "ru": "Испытывает трудности с тем, чтобы принести или протянуть предмет, чтобы поделиться им", "en": "Has difficulty bringing or holding out an object to share it"}}, {"id": "d5i3", "t": {"az": "Baxışla sizin diqqətinizi cəlb etməkdə çətinlik çəkir", "ru": "Испытывает трудности с привлечением вашего внимания взглядом", "en": "Has difficulty attracting your attention with gaze"}}]}, {"id": "d6", "title": {"az": "Sosial təbəssüm və sevincin paylaşılması", "ru": "Социальная улыбка и разделение радости", "en": "Social Smile and Sharing of Enjoyment"}, "task": {"az": "Birgə oyun (baloncuk, qıdıqlama, top) zamanı uşağın sevincinə baxılır.", "ru": "Наблюдают за проявлением радости ребёнка во время совместной игры (пузыри, щекотка, мяч).", "en": "The child's enjoyment is observed during joint play (bubbles, tickling, a ball)."}, "items": [{"id": "d6i1", "t": {"az": "Sizin təbəssümünüzə təbəssümlə cavab verməkdə çətinlik çəkir", "ru": "Испытывает трудности с ответной улыбкой на вашу улыбку", "en": "Has difficulty smiling back in response to your smile"}}, {"id": "d6i2", "t": {"az": "Sevincini başqası ilə bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с разделением радости с другим человеком", "en": "Has difficulty sharing enjoyment with another person"}}, {"id": "d6i3", "t": {"az": "Birgə fəaliyyətdən zövq almaqda çətinlik çəkir", "ru": "Испытывает трудности с получением удовольствия от совместной деятельности", "en": "Has difficulty enjoying joint activities"}}]}, {"id": "d7", "title": {"az": "Sosial təşəbbüslərin keyfiyyəti", "ru": "Качество социальных инициатив", "en": "Quality of Social Overtures"}, "task": {"az": "Seans boyu uşağın sizinlə əlaqə qurmaq cəhdlərinə baxılır.", "ru": "На протяжении сессии наблюдают за попытками ребёнка установить с вами контакт.", "en": "Throughout the session the child's attempts to make contact with you are observed."}, "items": [{"id": "d7i1", "t": {"az": "Ünsiyyət cəhdləri aydın deyil və ya vəziyyətə uyğun gəlmir", "ru": "Попытки общения неясны или не соответствуют ситуации", "en": "Overtures are unclear or inappropriate to the situation"}}, {"id": "d7i2", "t": {"az": "Sizi ünsiyyətə dəvət etməkdə çətinlik çəkir (məsələn, oyuna çağırmır)", "ru": "Испытывает трудности с приглашением вас к общению (например, не зовёт играть)", "en": "Has difficulty inviting you to interact (for example, does not ask you to play)"}}, {"id": "d7i3", "t": {"az": "Təşəbbüsləri yersiz anda olur", "ru": "Инициативы возникают в неподходящий момент", "en": "Overtures occur at inappropriate moments"}}]}, {"id": "d8", "title": {"az": "Qarşılıqlı ünsiyyət və söhbət", "ru": "Взаимное общение и беседа", "en": "Reciprocal Communication and Conversation"}, "task": {"az": "Şəkilli kitaba baxarkən və ya gündəlik mövzuda (məktəb, oyun, ailə) söhbət edilir.", "ru": "Беседа во время рассматривания книги с картинками или на бытовые темы (школа, игра, семья).", "en": "Conversation while looking at a picture book or about everyday topics (school, play, family)."}, "items": [{"id": "d8i1", "t": {"az": "Söhbətdə növbə gözləməkdə çətinlik çəkir", "ru": "Испытывает трудности с ожиданием своей очереди в беседе", "en": "Has difficulty waiting for a turn in conversation"}}, {"id": "d8i2", "t": {"az": "Söhbəti özü başlatmaqda və davam etdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с самостоятельным началом и поддержанием беседы", "en": "Has difficulty initiating and maintaining a conversation"}}, {"id": "d8i3", "t": {"az": "Sualınıza uyğun cavab verməkdə çətinlik çəkir", "ru": "Испытывает трудности с ответом, соответствующим вашему вопросу", "en": "Has difficulty giving an answer that fits your question"}}]}, {"id": "d9", "title": {"az": "Nitqin xüsusiyyətləri", "ru": "Особенности речи", "en": "Speech Characteristics"}, "task": {"az": "Seans boyu uşağın necə danışdığına qulaq asılır.", "ru": "На протяжении сессии прислушиваются к тому, как ребёнок говорит.", "en": "Throughout the session the examiner listens to how the child speaks."}, "items": [{"id": "d9i1", "t": {"az": "Səsi monoton, robot kimi və ya qeyri-adi tonda səslənir", "ru": "Голос монотонный, «роботизированный» или необычный по тону", "en": "Voice sounds monotone, robotic, or unusual in tone"}}, {"id": "d9i2", "t": {"az": "Eşitdiyi sözləri təkrar edir (exolaliya) və ya qəlibləşmiş ifadələr işlədir", "ru": "Повторяет услышанные слова (эхолалия) или использует шаблонные фразы", "en": "Repeats words heard (echolalia) or uses stereotyped phrases"}}, {"id": "d9i3", "t": {"az": "Nitqin sürəti və ucalığı vəziyyətə uyğun gəlmir", "ru": "Темп и громкость речи не соответствуют ситуации", "en": "Rate and volume of speech do not match the situation"}}]}, {"id": "d10", "title": {"az": "Funksional və simvolik oyun", "ru": "Функциональная и символическая игра", "en": "Functional and Symbolic Play"}, "task": {"az": "Uşağa oyuncaqlar (kuklalar, qab-qacaq, maşın) verilir və necə oynadığına baxılır.", "ru": "Ребёнку дают игрушки (куклы, посуду, машинки) и наблюдают, как он играет.", "en": "The child is given toys (dolls, dishes, cars) and the examiner observes how he or she plays."}, "items": [{"id": "d10i1", "t": {"az": "Oyuncaqlardan təyinatına uyğun istifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с использованием игрушек по назначению", "en": "Has difficulty using toys for their intended purpose"}}, {"id": "d10i2", "t": {"az": "Uydurma oyuna keçməkdə çətinlik çəkir (məsələn, boş qabdan «içmək»)", "ru": "Испытывает трудности с переходом к воображаемой игре (например, «пить» из пустой чашки)", "en": "Has difficulty moving to pretend play (for example, \"drinking\" from an empty cup)"}}, {"id": "d10i3", "t": {"az": "Oyunda çeviklik və yaradıcılıq göstərməkdə çətinlik çəkir", "ru": "Испытывает трудности с проявлением гибкости и творчества в игре", "en": "Has difficulty showing flexibility and creativity in play"}}]}, {"id": "d11", "title": {"az": "Təxəyyül və yaradıcılıq", "ru": "Воображение и творчество", "en": "Imagination and Creativity"}, "task": {"az": "Doğum günü süfrəsi və ya mətbəx oyunu qurulur, uşağın süjet qurub-qurmadığına baxılır.", "ru": "Организуют игру в день рождения или кухню и наблюдают, строит ли ребёнок сюжет.", "en": "A birthday party or kitchen play scene is set up and the examiner observes whether the child builds a storyline."}, "items": [{"id": "d11i1", "t": {"az": "Özü yeni oyun süjeti qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с самостоятельным построением нового игрового сюжета", "en": "Has difficulty creating a new play storyline independently"}}, {"id": "d11i2", "t": {"az": "Bir əşyanı başqası yerinə istifadə etməkdə çətinlik çəkir (məsələn, kubu telefon kimi)", "ru": "Испытывает трудности с использованием одного предмета вместо другого (например, кубика как телефона)", "en": "Has difficulty using one object to stand for another (for example, a block as a phone)"}}, {"id": "d11i3", "t": {"az": "Rol oyununda iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в ролевой игре", "en": "Has difficulty taking part in role play"}}]}, {"id": "d12", "title": {"az": "Stereotip hərəkətlər və manerizmlər", "ru": "Стереотипные движения и манеризмы", "en": "Stereotyped Movements and Mannerisms"}, "task": {"az": "Seans boyu uşağın əl, barmaq və bədən hərəkətlərinə baxılır.", "ru": "На протяжении сессии наблюдают за движениями рук, пальцев и тела ребёнка.", "en": "Throughout the session the child's hand, finger, and body movements are observed."}, "items": [{"id": "d12i1", "t": {"az": "Əl və ya barmaqlarla təkrarlanan hərəkətlər edir", "ru": "Совершает повторяющиеся движения руками или пальцами", "en": "Makes repetitive hand or finger movements"}}, {"id": "d12i2", "t": {"az": "Bədənin təkrarlanan hərəkətləri var (yırğalanma, sıçrama)", "ru": "Совершает повторяющиеся движения телом (раскачивание, подпрыгивание)", "en": "Makes repetitive body movements (rocking, jumping)"}}, {"id": "d12i3", "t": {"az": "Həyəcan və ya gərginlik zamanı bu hərəkətlər artır", "ru": "Эти движения усиливаются при возбуждении или напряжении", "en": "These movements increase with excitement or tension"}}]}, {"id": "d13", "title": {"az": "Predmetlərin təkrarlanan istifadəsi", "ru": "Повторяющееся использование предметов", "en": "Repetitive Use of Objects"}, "task": {"az": "Oyuncaqlar və kublar verilir, uşağın onları necə işlətdiyinə baxılır.", "ru": "Ребёнку дают игрушки и кубики и наблюдают, как он с ними обращается.", "en": "The child is given toys and blocks and the examiner observes how he or she handles them."}, "items": [{"id": "d13i1", "t": {"az": "Əşyaları təkrar sıralayır və ya fırladır", "ru": "Повторно выстраивает в ряд или вращает предметы", "en": "Repeatedly lines up or spins objects"}}, {"id": "d13i2", "t": {"az": "Oyuncağın yalnız bir hissəsi ilə məşğul olur (məsələn, maşının təkəri)", "ru": "Занимается только одной частью игрушки (например, колесом машинки)", "en": "Focuses on only one part of a toy (for example, a car wheel)"}}, {"id": "d13i3", "t": {"az": "Eyni hərəkəti dəfələrlə təkrarlayır", "ru": "Многократно повторяет одно и то же действие", "en": "Repeats the same action many times"}}]}, {"id": "d14", "title": {"az": "Məhdud maraqlar və rituallar", "ru": "Ограниченные интересы и ритуалы", "en": "Restricted Interests and Rituals"}, "task": {"az": "Uşağın sevdiyi mövzuları söhbətdə və oyunda müşahidə edin, istəsəniz bir tapşırığı yarımçıq dayandırıb reaksiyasına baxın.", "ru": "Наблюдайте за любимыми темами ребёнка в беседе и игре; при желании прервите одно задание и посмотрите на реакцию.", "en": "Observe the child's favorite topics in conversation and play; if desired, stop one task partway and observe the reaction."}, "items": [{"id": "d14i1", "t": {"az": "Çox dar və qeyri-adi mövzuya intensiv bağlıdır", "ru": "Интенсивно увлечён очень узкой или необычной темой", "en": "Is intensely absorbed in a very narrow or unusual topic"}}, {"id": "d14i2", "t": {"az": "Eyni qaydaya və ya ardıcıllığa israrla ehtiyac duyur", "ru": "Настойчиво требует соблюдения одного и того же порядка или последовательности", "en": "Insists on the same routine or sequence"}}, {"id": "d14i3", "t": {"az": "Planın və ya yerin dəyişməsinə güclü müqavimət göstərir", "ru": "Сильно сопротивляется изменению плана или места", "en": "Strongly resists changes of plan or place"}}]}, {"id": "d15", "title": {"az": "Sensor maraqlar", "ru": "Сенсорные интересы", "en": "Sensory Interests"}, "task": {"az": "Oyuncaq və əşyalarla oynayarkən uşağın onlara necə yanaşdığına baxılır.", "ru": "Наблюдают, как ребёнок обращается с игрушками и предметами во время игры.", "en": "The examiner observes how the child approaches toys and objects during play."}, "items": [{"id": "d15i1", "t": {"az": "Əşyaları qoxulayır, yalayır və ya çox yaxından baxır", "ru": "Обнюхивает, облизывает предметы или рассматривает их очень близко", "en": "Smells or licks objects, or looks at them from very close"}}, {"id": "d15i2", "t": {"az": "İşığa, səsə və ya toxunuşa qeyri-adi maraq göstərir", "ru": "Проявляет необычный интерес к свету, звуку или прикосновению", "en": "Shows unusual interest in light, sound, or touch"}}, {"id": "d15i3", "t": {"az": "Müəyyən sensor təsiri təkrar-təkrar axtarır", "ru": "Многократно ищет определённое сенсорное воздействие", "en": "Repeatedly seeks a particular sensory input"}}]}], "specialist": [{"az": "ADOS-2 müşahidələrini inkişaf tarixçəsi və digər mənbələrlə birlikdə qiymətləndirin.", "ru": "Оценивайте наблюдения ADOS-2 вместе с историей развития и другими источниками.", "en": "Interpret ADOS-2 observations together with developmental history and other sources."}, {"az": "Sosial-ünsiyyət çətinlikləri davamlıdırsa, ADI-R müsahibəsi ilə tamamlayın.", "ru": "При устойчивых социально-коммуникативных трудностях дополните интервью ADI-R.", "en": "If social-communication difficulties persist, complement with the ADI-R interview."}, {"az": "Komanda müzakirəsi və klinik mülahizə ilə yekunlaşdırın.", "ru": "Завершите командным обсуждением и клиническим суждением.", "en": "Conclude with team discussion and clinical judgment."}], "parentIntro": {"az": "Aşağıdakılar diaqnoz deyil — uşağınıza gündəlik həyatda dəstək olmaq üçün sadə addımlardır.", "ru": "Ниже — не диагноз, а простые шаги поддержки ребёнка в повседневной жизни.", "en": "The following is not a diagnosis — these are simple steps to support your child day to day."}, "parentTips": [{"az": "Göz təması üçün uşağın sevdiyi oyuncağı öz üzünüzün yanında tutun.", "ru": "Для зрительного контакта держите любимую игрушку у своего лица.", "en": "For eye contact, hold a favorite toy near your face."}, {"az": "Qısa, aydın cümlələrlə danışın və cavab üçün vaxt verin.", "ru": "Говорите короткими ясными фразами и давайте время на ответ.", "en": "Speak in short, clear sentences and allow time to respond."}, {"az": "Gündəlik rejimi sabit saxlayın — bu, təhlükəsizlik hissi verir.", "ru": "Поддерживайте стабильный распорядок — это даёт чувство безопасности.", "en": "Keep a steady daily routine — it provides a sense of security."}], "games": [{"az": "'Növbə ilə' oyunu: topu bir-birinizə yuvarlayın, hər dəfə ad deyin.", "ru": "Игра «по очереди»: катайте мяч друг другу, называя имя.", "en": "'Take turns' game: roll a ball to each other, saying the name each time."}, {"az": "Köpük üfürmək: birgə diqqət və paylaşılan sevinc üçün.", "ru": "Пускание пузырей: для совместного внимания и общей радости.", "en": "Blowing bubbles: for joint attention and shared joy."}, {"az": "Güzgü oyunu: uşağın hərəkət və səslərini təkrarlayın.", "ru": "Игра в зеркало: повторяйте движения и звуки ребёнка.", "en": "Mirror game: imitate the child's movements and sounds."}]}, "adir": {"id": "adir", "name": "ADI-R", "full": {"az": "Otizm Diaqnostik Müsahibə — Yenidən işlənmiş", "ru": "Диагностическое интервью при аутизме — переработанное", "en": "Autism Diagnostic Interview — Revised"}, "age": {"az": "Zehni yaşı ~2 ildən yuxarı uşaq və böyüklər üçün", "ru": "Дети и взрослые с умственным возрастом ~от 2 лет", "en": "Children and adults with mental age ~2 years and above"}, "summary": {"az": "Valideyn/qəyyumla aparılan strukturlaşdırılmış müsahibə. Uşağın inkişaf tarixçəsini və cari davranışını dərindən araşdırır.", "ru": "Структурированное интервью с родителем/опекуном. Глубоко исследует историю развития и текущее поведение ребёнка.", "en": "A structured interview with the parent/caregiver. Explores the child's developmental history and current behavior in depth."}, "advantages": [{"az": "Dərin inkişaf tarixçəsi verir", "ru": "Даёт глубокую историю развития", "en": "Provides a deep developmental history"}, {"az": "ADOS-2 müşahidəsini güclü tamamlayır", "ru": "Хорошо дополняет наблюдение ADOS-2", "en": "Strongly complements ADOS-2 observation"}, {"az": "Erkən əlamətlərin vaxtını dəqiqləşdirir", "ru": "Уточняет время появления ранних признаков", "en": "Clarifies the timing of early signs"}, {"az": "Ailə kontekstini nəzərə alır", "ru": "Учитывает семейный контекст", "en": "Takes family context into account"}], "instruction": {"howto": [{"az": "Uşağı yaxşı tanıyan valideyn/qəyyumla aparın.", "ru": "Проводите с родителем/опекуном, хорошо знающим ребёнка.", "en": "Conduct with a parent/caregiver who knows the child well."}, {"az": "Həm keçmiş (4–5 yaş), həm cari davranışı soruşun.", "ru": "Спрашивайте и о прошлом (4–5 лет), и о текущем поведении.", "en": "Ask about both the past (ages 4–5) and current behavior."}, {"az": "Konkret nümunələr və tezlik üzərində dayanın.", "ru": "Сосредоточьтесь на конкретных примерах и частоте.", "en": "Focus on concrete examples and frequency."}], "methods": [{"az": "Yarımstrukturlaşdırılmış müsahibə", "ru": "Полуструктурированное интервью", "en": "Semi-structured interview"}, {"az": "Davranış nümunələrinin toplanması", "ru": "Сбор примеров поведения", "en": "Collection of behavior examples"}], "scoring": [{"az": "Cavablar üç sahə üzrə kodlanır və alqoritmə yığılır.", "ru": "Ответы кодируются по трём областям и сводятся в алгоритм.", "en": "Responses are coded across three domains and combined into an algorithm."}, {"az": "Kəsim balları yalnız rəsmi protokol üzrə tətbiq olunur.", "ru": "Пороговые баллы применяются только по официальному протоколу.", "en": "Cutoff scores apply only per the official protocol."}]}, "official": [{"label": {"az": "Sosial təsir sahəsi balı", "ru": "Балл области соц. взаимодействия", "en": "Social interaction domain score"}, "hint": {"az": "rəsmi alqoritmdən", "ru": "из официального алгоритма", "en": "from official algorithm"}}, {"label": {"az": "Ünsiyyət sahəsi balı", "ru": "Балл области коммуникации", "en": "Communication domain score"}, "hint": {"az": "rəsmi alqoritmdən", "ru": "из официального алгоритма", "en": "from official algorithm"}}, {"label": {"az": "Təkrarlanan davranış balı", "ru": "Балл повторяющегося поведения", "en": "Repetitive behavior score"}, "hint": {"az": "rəsmi alqoritmdən", "ru": "из официального алгоритма", "en": "from official algorithm"}}], "domains": [{"id": "d1", "title": {"az": "Erkən inkişaf və mərhələlər", "ru": "Раннее развитие и вехи", "en": "Early Development and Milestones"}, "task": {"az": "Valideynə sual: uşaq neçə aylıqda oturdu, yeridi? İlk narahatlığı nə vaxt və nədən hiss etdiniz?", "ru": "Вопрос родителю: в каком возрасте ребёнок начал сидеть, ходить? Когда и по какому поводу вы впервые почувствовали беспокойство?", "en": "Question to the parent: at what age did the child sit and walk? When, and about what, did you first feel concerned?"}, "items": [{"id": "d1i1", "t": {"az": "Əsas inkişaf mərhələləri (oturma, yeriş) yaşa görə gecikib", "ru": "Основные вехи развития (сидение, ходьба) наступили позже возрастной нормы", "en": "Key developmental milestones (sitting, walking) were delayed for age"}}, {"id": "d1i2", "t": {"az": "Körpəlikdə sosial maraq və cavab (gülümsəmə, baxış) zəif olub", "ru": "В младенчестве социальный интерес и отклик (улыбка, взгляд) были слабыми", "en": "In infancy, social interest and responsiveness (smiling, gaze) were weak"}}, {"id": "d1i3", "t": {"az": "Valideyn ilk dəfə nə vaxtsa inkişafla bağlı narahatlıq hiss edib", "ru": "Родитель в какой-то момент почувствовал беспокойство по поводу развития", "en": "The parent at some point felt concerned about the child's development"}}]}, {"id": "d2", "title": {"az": "Dilin yaranması və itkisi", "ru": "Появление и утрата речи", "en": "Language Onset and Loss"}, "task": {"az": "Valideynə sual: ilk söz və ilk cümləni nə vaxt dedi? Əvvəl danışdığı sözləri sonra tərk etdimi?", "ru": "Вопрос родителю: когда ребёнок произнёс первое слово и первую фразу? Переставал ли он говорить слова, которые произносил раньше?", "en": "Question to the parent: when did the child say the first word and the first sentence? Did the child stop using words he or she used before?"}, "items": [{"id": "d2i1", "t": {"az": "İlk sözlər və cümlələr yaşa görə gec yaranıb", "ru": "Первые слова и фразы появились позже возрастной нормы", "en": "First words and phrases appeared later than expected for age"}}, {"id": "d2i2", "t": {"az": "Əvvəl qazanılmış nitq və ya bacarıq sonradan itib", "ru": "Ранее приобретённая речь или навык впоследствии были утрачены", "en": "Previously acquired speech or skills were later lost"}}, {"id": "d2i3", "t": {"az": "Dil inkişafında dayanma və ya geriləmə dövrü olub", "ru": "Был период остановки или регресса в развитии речи", "en": "There was a period of plateau or regression in language development"}}]}, {"id": "d3", "title": {"az": "Reseptiv dil", "ru": "Импрессивная речь", "en": "Receptive Language"}, "task": {"az": "Valideynə sual: sadə göstərişləri («gətir», «otur») başa düşür? Adını çağıranda dönür?", "ru": "Вопрос родителю: понимает ли ребёнок простые просьбы («принеси», «садись»)? Оборачивается ли, когда его зовут по имени?", "en": "Question to the parent: does the child understand simple instructions (\"bring it\", \"sit down\")? Does the child turn when called by name?"}, "items": [{"id": "d3i1", "t": {"az": "Sadə göstəriş və əşya adlarını başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием простых инструкций и названий предметов", "en": "Has difficulty understanding simple instructions and object names"}}, {"id": "d3i2", "t": {"az": "Adı çağırılanda cavab verməyib və ya gec cavab verib", "ru": "Не откликался или откликался с задержкой, когда его звали по имени", "en": "Did not respond, or responded late, when called by name"}}, {"id": "d3i3", "t": {"az": "Bir neçə addımlı şifahi göstərişi izləməkdə çətinlik çəkir", "ru": "Испытывает трудности с выполнением многошаговых устных инструкций", "en": "Has difficulty following multi-step verbal instructions"}}]}, {"id": "d4", "title": {"az": "Ekspressiv dil və söhbət", "ru": "Экспрессивная речь и беседа", "en": "Expressive Language and Conversation"}, "task": {"az": "Valideynə sual: istəyini sözlə necə bildirir? Sizinlə qarşılıqlı söhbət edə bilir?", "ru": "Вопрос родителю: как ребёнок выражает желания словами? Может ли он вести с вами диалог?", "en": "Question to the parent: how does the child express wishes in words? Can the child carry on a back-and-forth conversation with you?"}, "items": [{"id": "d4i1", "t": {"az": "İstəklərini sözlə ifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с выражением желаний словами", "en": "Has difficulty expressing wishes in words"}}, {"id": "d4i2", "t": {"az": "Qarşılıqlı söhbəti davam etdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с поддержанием диалога", "en": "Has difficulty sustaining a reciprocal conversation"}}, {"id": "d4i3", "t": {"az": "Dildən sosial məqsədlə (salamlaşma, soruşma) istifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с использованием речи в социальных целях (приветствие, вопросы)", "en": "Has difficulty using language for social purposes (greeting, asking questions)"}}]}, {"id": "d5", "title": {"az": "Stereotip və təkrarlanan nitq", "ru": "Стереотипная и повторяющаяся речь", "en": "Stereotyped and Repetitive Speech"}, "task": {"az": "Valideynə sual: eşitdiyi sözləri və ya çizgi filmindən cümlələri təkrar edir? «Mən» və «sən» sözlərini qarışdırır?", "ru": "Вопрос родителю: повторяет ли ребёнок услышанные слова или фразы из мультфильма? Путает ли «я» и «ты»?", "en": "Question to the parent: does the child repeat words heard, or sentences from cartoons? Does the child confuse \"I\" and \"you\"?"}, "items": [{"id": "d5i1", "t": {"az": "Eşitdiyi sözləri dərhal və ya sonradan təkrar edir (exolaliya)", "ru": "Повторяет услышанные слова сразу или спустя время (эхолалия)", "en": "Repeats words heard, immediately or later (echolalia)"}}, {"id": "d5i2", "t": {"az": "Eyni qəlibləşmiş cümlələri dəfələrlə işlədir", "ru": "Многократно использует одни и те же шаблонные фразы", "en": "Repeatedly uses the same stereotyped phrases"}}, {"id": "d5i3", "t": {"az": "«Mən» və «sən» əvəzliklərini qarışdırır", "ru": "Путает местоимения «я» и «ты»", "en": "Reverses the pronouns \"I\" and \"you\""}}]}, {"id": "d6", "title": {"az": "Qeyri-verbal ünsiyyət (tarixçə)", "ru": "Невербальное общение (анамнез)", "en": "Nonverbal Communication (history)"}, "task": {"az": "Valideynə sual: kiçik yaşda barmağı ilə göstərirdi? Baş yelləmə kimi jestlərdən istifadə edirdi?", "ru": "Вопрос родителю: показывал ли ребёнок пальцем в раннем возрасте? Использовал ли жесты, например кивок?", "en": "Question to the parent: did the child point at an early age? Did the child use gestures such as nodding?"}, "items": [{"id": "d6i1", "t": {"az": "Jest və mimikadan ünsiyyətdə istifadə etməkdə çətinlik çəkib", "ru": "Испытывал трудности с использованием жестов и мимики для общения", "en": "Had difficulty using gestures and facial expression to communicate"}}, {"id": "d6i2", "t": {"az": "Barmaqla göstərmə və baş yelləmə kimi işarələr zəif olub", "ru": "Указательный жест и кивок были выражены слабо", "en": "Pointing and nodding were weak"}}, {"id": "d6i3", "t": {"az": "Bədən dilini sosial məqsədlə istifadə etməkdə çətinlik çəkib", "ru": "Испытывал трудности с использованием языка тела в социальных целях", "en": "Had difficulty using body language for social purposes"}}]}, {"id": "d7", "title": {"az": "Göz təması və sosial təbəssüm", "ru": "Зрительный контакт и социальная улыбка", "en": "Eye Contact and Social Smile"}, "task": {"az": "Valideynə sual: körpəykən sizin üzünüzə baxıb gülümsəyirdi? İndi danışarkən sizə baxır?", "ru": "Вопрос родителю: в младенчестве ребёнок смотрел вам в лицо и улыбался? Смотрит ли он на вас, когда говорит?", "en": "Question to the parent: as an infant, did the child look at your face and smile? Does the child look at you when speaking?"}, "items": [{"id": "d7i1", "t": {"az": "Kiçik yaşda və ya indi göz təması zəif olub", "ru": "В раннем возрасте или сейчас зрительный контакт был слабым", "en": "Eye contact was poor in early childhood or is poor now"}}, {"id": "d7i2", "t": {"az": "Sosial təbəssüm gec yaranıb və ya az olub", "ru": "Социальная улыбка появилась поздно или проявлялась редко", "en": "Social smile appeared late or was infrequent"}}, {"id": "d7i3", "t": {"az": "Baxışı ünsiyyət məqsədilə istifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с использованием взгляда для общения", "en": "Has difficulty using gaze to communicate"}}]}, {"id": "d8", "title": {"az": "Yaşıdlarla münasibətlər", "ru": "Отношения со сверстниками", "en": "Peer Relationships"}, "task": {"az": "Valideynə sual: həyətdə, bağçada və ya məktəbdə uşaqlarla necə oynayır? Dostu var?", "ru": "Вопрос родителю: как ребёнок играет с детьми во дворе, в саду или в школе? Есть ли у него друг?", "en": "Question to the parent: how does the child play with other children in the yard, at kindergarten, or at school? Does the child have a friend?"}, "items": [{"id": "d8i1", "t": {"az": "Yaşıdları ilə oyun və dostluq qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с игрой и дружбой со сверстниками", "en": "Has difficulty playing and forming friendships with peers"}}, {"id": "d8i2", "t": {"az": "Qrup oyununda iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в групповой игре", "en": "Has difficulty taking part in group play"}}, {"id": "d8i3", "t": {"az": "Yaşıdlara maraq göstərmir və ya təkbaşına oynamağı üstün tutur", "ru": "Не проявляет интереса к сверстникам или предпочитает играть один", "en": "Shows no interest in peers or prefers to play alone"}}]}, {"id": "d9", "title": {"az": "Sevinc və maraqların paylaşılması", "ru": "Разделение радости и интересов", "en": "Sharing Enjoyment and Interests"}, "task": {"az": "Valideynə sual: sevdiyi şeyi sizə göstərir? Uğur qazananda sizə baxıb sevinir?", "ru": "Вопрос родителю: показывает ли ребёнок вам то, что любит? Радуется ли, глядя на вас, когда у него что-то получается?", "en": "Question to the parent: does the child show you things he or she likes? When successful, does the child look at you and share the joy?"}, "items": [{"id": "d9i1", "t": {"az": "Maraqlı şeyləri başqası ilə bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с тем, чтобы делиться интересным с другими", "en": "Has difficulty sharing interesting things with others"}}, {"id": "d9i2", "t": {"az": "Sevincini valideyni ilə paylaşmaqda çətinlik çəkir", "ru": "Испытывает трудности с разделением радости с родителем", "en": "Has difficulty sharing enjoyment with the parent"}}, {"id": "d9i3", "t": {"az": "Nailiyyətini göstərmək istəmir", "ru": "Не стремится показывать свои достижения", "en": "Does not seek to show his or her achievements"}}]}, {"id": "d10", "title": {"az": "Emosional qarşılıqlılıq", "ru": "Эмоциональная взаимность", "en": "Emotional Reciprocity"}, "task": {"az": "Valideynə sual: ağlayanda və ya bərk narahat olanda uşaq necə reaksiya verir? Özü sizdən təsəlli axtarır?", "ru": "Вопрос родителю: как ребёнок реагирует, когда вы плачете или сильно расстроены? Ищет ли он утешения сам?", "en": "Question to the parent: how does the child react when you cry or are very upset? Does the child seek comfort on his or her own?"}, "items": [{"id": "d10i1", "t": {"az": "Başqasının hissinə uyğun reaksiya verməkdə çətinlik çəkir", "ru": "Испытывает трудности с адекватной реакцией на чувства другого человека", "en": "Has difficulty responding appropriately to another person's feelings"}}, {"id": "d10i2", "t": {"az": "Təsəlli axtarmaqda və ya təklif etməkdə çətinlik çəkir", "ru": "Испытывает трудности с поиском утешения или попытками утешить", "en": "Has difficulty seeking or offering comfort"}}, {"id": "d10i3", "t": {"az": "Hissi qarşılıqlı bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с взаимным разделением чувств", "en": "Has difficulty sharing feelings reciprocally"}}]}, {"id": "d11", "title": {"az": "Təxəyyül və rol oyunu (tarixçə)", "ru": "Воображение и ролевая игра (анамнез)", "en": "Imagination and Role Play (history)"}, "task": {"az": "Valideynə sual: kiçikliyində oyuncaqla «yemək yedirmək», «çay içmək» kimi uydurma oyun oynayırdı?", "ru": "Вопрос родителю: играл ли ребёнок в раннем возрасте в воображаемые игры, например «кормить» игрушку или «пить чай»?", "en": "Question to the parent: in early childhood, did the child engage in pretend play, such as \"feeding\" a toy or \"having tea\"?"}, "items": [{"id": "d11i1", "t": {"az": "Uydurma oyun yaşa görə gec yaranıb və ya heç yaranmayıb", "ru": "Воображаемая игра появилась позже возрастной нормы или не появилась вовсе", "en": "Pretend play appeared later than expected for age or did not appear at all"}}, {"id": "d11i2", "t": {"az": "Rol və süjetli oyunda çətinlik çəkib", "ru": "Испытывал трудности с ролевой и сюжетной игрой", "en": "Had difficulty with role play and storyline play"}}, {"id": "d11i3", "t": {"az": "Oyunda çeviklik və yaradıcılıq zəif olub", "ru": "В игре было мало гибкости и творчества", "en": "Play showed little flexibility and creativity"}}]}, {"id": "d12", "title": {"az": "Məhdud, dar maraqlar", "ru": "Ограниченные узкие интересы", "en": "Restricted, Narrow Interests"}, "task": {"az": "Valideynə sual: uşağın xüsusi maraq sahəsi var (məsələn, yalnız qatarlar)? Nə qədər vaxt ayırır?", "ru": "Вопрос родителю: есть ли у ребёнка особая область интересов (например, только поезда)? Сколько времени он ей уделяет?", "en": "Question to the parent: does the child have a special area of interest (for example, only trains)? How much time does he or she devote to it?"}, "items": [{"id": "d12i1", "t": {"az": "Qeyri-adi və ya çox dar maraq sahəsi var", "ru": "Имеет необычную или очень узкую область интересов", "en": "Has an unusual or very narrow area of interest"}}, {"id": "d12i2", "t": {"az": "Bu maraqla həddindən artıq məşğul olur", "ru": "Чрезмерно занят этим интересом", "en": "Is excessively preoccupied with this interest"}}, {"id": "d12i3", "t": {"az": "Maraq gündəlik həyata mane olur", "ru": "Интерес мешает повседневной жизни", "en": "The interest interferes with daily life"}}]}, {"id": "d13", "title": {"az": "Rituallar və gündəlik qaydalar", "ru": "Ритуалы и бытовые правила", "en": "Rituals and Routines"}, "task": {"az": "Valideynə sual: hər gün eyni qaydada etməli olduğu şeylər var? Dəyişiklik olanda nə baş verir?", "ru": "Вопрос родителю: есть ли действия, которые ребёнок должен каждый день выполнять в одном и том же порядке? Что происходит при изменении?", "en": "Question to the parent: are there things the child must do in the same way every day? What happens when something changes?"}, "items": [{"id": "d13i1", "t": {"az": "Müəyyən ritualları mütləq yerinə yetirməyə ehtiyac duyur", "ru": "Испытывает потребность обязательно выполнять определённые ритуалы", "en": "Feels a need to carry out certain rituals without fail"}}, {"id": "d13i2", "t": {"az": "Gündəlik qaydanın pozulmasına güclü narahatlıq göstərir", "ru": "Выраженно тревожится при нарушении привычного порядка", "en": "Shows marked distress when the daily routine is disrupted"}}, {"id": "d13i3", "t": {"az": "Eyniliyə güclü tələbat var", "ru": "Сильная потребность в неизменности", "en": "Has a strong need for sameness"}}]}, {"id": "d14", "title": {"az": "Motor manerizmlər və sensor", "ru": "Моторные манеризмы и сенсорные особенности", "en": "Motor Mannerisms and Sensory Features"}, "task": {"az": "Valideynə sual: əl-barmaq hərəkətləri, yırğalanma var? Səs, toxunuş və qoxuya qeyri-adi reaksiyası var? Əlamətlər neçə yaşından başlayıb?", "ru": "Вопрос родителю: бывают ли движения рук и пальцев, раскачивание? Необычно ли ребёнок реагирует на звуки, прикосновения, запахи? С какого возраста появились эти признаки?", "en": "Question to the parent: are there hand or finger movements or rocking? Does the child react unusually to sounds, touch, or smells? At what age did these signs begin?"}, "items": [{"id": "d14i1", "t": {"az": "Təkrarlanan motor hərəkətlər (əl çalma, yırğalanma) var", "ru": "Повторяющиеся двигательные действия (хлопанье руками, раскачивание)", "en": "Repetitive motor movements (hand flapping, rocking)"}}, {"id": "d14i2", "t": {"az": "Səs, toxunuş və ya qoxuya qeyri-adi reaksiya verir", "ru": "Необычно реагирует на звуки, прикосновения или запахи", "en": "Reacts unusually to sounds, touch, or smells"}}, {"id": "d14i3", "t": {"az": "Əlamətlər erkən yaşdan başlayıb və ya əvvəlki bacarıqlar geriləyib", "ru": "Признаки появились в раннем возрасте или ранее приобретённые навыки регрессировали", "en": "Signs began at an early age, or previously acquired skills regressed"}}]}], "specialist": [{"az": "ADI-R tarixçəsini ADOS-2 birbaşa müşahidəsi ilə tutuşdurun.", "ru": "Сопоставьте историю ADI-R с прямым наблюдением ADOS-2.", "en": "Cross-check the ADI-R history against direct ADOS-2 observation."}, {"az": "Tarixçə ilə cari davranış arasında uyğunsuzluğu qeyd edin.", "ru": "Отметьте расхождения между историей и текущим поведением.", "en": "Note discrepancies between history and current behavior."}, {"az": "Tibbi və genetik amilləri istisna etmək üçün əlavə müayinə tövsiyə edin.", "ru": "Рекомендуйте доп. обследование для исключения медицинских и генетических факторов.", "en": "Recommend further evaluation to rule out medical and genetic factors."}], "parentIntro": {"az": "Bu müsahibə uşağınızın tarixçəsini anlamağa kömək edir. Cavablarınız nə qədər dəqiq olsa, dəstək bir o qədər uyğun olar.", "ru": "Это интервью помогает понять историю вашего ребёнка. Чем точнее ответы, тем точнее поддержка.", "en": "This interview helps understand your child's history. The more precise your answers, the more fitting the support."}, "parentTips": [{"az": "Uşağın kiçik yaş videolarına baxmaq xatırlamağa kömək edə bilər.", "ru": "Просмотр видео раннего возраста помогает вспомнить.", "en": "Watching early-age videos can help you remember."}, {"az": "Müsbət bacarıqları da qeyd edin — onlar dəstəyin əsasıdır.", "ru": "Отмечайте и сильные навыки — они основа поддержки.", "en": "Note strengths too — they are the basis of support."}, {"az": "Çətinlik gördüyünüz anları konkret nümunələrlə yazın.", "ru": "Записывайте трудные моменты конкретными примерами.", "en": "Write down difficult moments with concrete examples."}], "games": [{"az": "Birgə şəkil albomu: keçmiş anları danışaraq nitqi və yaddaşı dəstəkləyin.", "ru": "Совместный фотоальбом: проговаривая прошлое, поддерживайте речь и память.", "en": "Shared photo album: talk through past moments to support speech and memory."}, {"az": "Növbəli nağıl: bir cümləni siz, birini uşaq deyir.", "ru": "Сказка по очереди: одно предложение вы, одно ребёнок.", "en": "Turn-taking story: you say one sentence, the child the next."}]}, "wiscv": {"id": "wiscv", "name": "WISC-V", "full": {"az": "Wechsler Uşaqlar üçün İntellekt Şkalası, 5-ci nəşr", "ru": "Шкала интеллекта Векслера для детей, 5-е изд.", "en": "Wechsler Intelligence Scale for Children, 5th ed."}, "age": {"az": "6 yaş 0 ay – 16 yaş 11 ay", "ru": "6 лет 0 мес. – 16 лет 11 мес.", "en": "6 years 0 months – 16 years 11 months"}, "summary": {"az": "Koqnitiv qabiliyyətləri beş əsas indeks üzrə ölçən geniş istifadə olunan intellekt şkalası. Güclü və zəif tərəfləri profil şəklində göstərir.", "ru": "Широко используемая шкала интеллекта, измеряющая когнитивные способности по пяти основным индексам. Показывает профиль сильных и слабых сторон.", "en": "A widely used intelligence scale measuring cognitive ability across five primary indices. Shows a profile of strengths and weaknesses."}, "advantages": [{"az": "Beş ayrı koqnitiv indeks verir", "ru": "Даёт пять отдельных когнитивных индексов", "en": "Provides five distinct cognitive indices"}, {"az": "Öyrənmə çətinliklərinin profilini açır", "ru": "Раскрывает профиль трудностей обучения", "en": "Reveals the profile of learning difficulties"}, {"az": "Təhsil planlaması üçün dəyərli", "ru": "Ценна для планирования обучения", "en": "Valuable for educational planning"}, {"az": "Güclü tərəflərə əsaslanan dəstəyə imkan verir", "ru": "Позволяет опираться на сильные стороны", "en": "Enables strength-based support"}], "instruction": {"howto": [{"az": "Sakit, fasiləsiz mühitdə təkbətək keçirin.", "ru": "Проводите наедине, без перерывов, в тихой обстановке.", "en": "Administer one-on-one in a quiet, uninterrupted setting."}, {"az": "Standart ardıcıllıq və təlimatlara dəqiq əməl edin.", "ru": "Точно следуйте стандартному порядку и инструкциям.", "en": "Follow the standard order and instructions precisely."}, {"az": "Uşağın yorğunluğunu izləyin, lazımda fasilə verin.", "ru": "Следите за утомлением ребёнка, делайте перерывы.", "en": "Watch for fatigue; allow breaks as needed."}], "methods": [{"az": "Subtestlər üzrə birbaşa tapşırıqlar", "ru": "Прямые задания по субтестам", "en": "Direct subtest tasks"}, {"az": "Şifahi və performans tapşırıqlarının birləşməsi", "ru": "Сочетание вербальных и performance-заданий", "en": "A mix of verbal and performance tasks"}], "scoring": [{"az": "Xam ballar normalara görə standart ballara çevrilir.", "ru": "Сырые баллы переводятся в стандартные по нормам.", "en": "Raw scores convert to standard scores per norms."}, {"az": "İndeks və ümumi IQ yalnız rəsmi cədvəllərlə hesablanır.", "ru": "Индексы и общий IQ рассчитываются только по официальным таблицам.", "en": "Index and Full Scale IQ are computed only with official tables."}]}, "official": [{"label": {"az": "Şifahi Dərketmə (VCI)", "ru": "Вербальное понимание (VCI)", "en": "Verbal Comprehension (VCI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "Vizual-Məkan (VSI)", "ru": "Зрительно-пространственный (VSI)", "en": "Visual Spatial (VSI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "Məntiqi Mühakimə (FRI)", "ru": "Подвижный интеллект (FRI)", "en": "Fluid Reasoning (FRI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "İşlək Yaddaş (WMI)", "ru": "Рабочая память (WMI)", "en": "Working Memory (WMI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "Emal Sürəti (PSI)", "ru": "Скорость обработки (PSI)", "en": "Processing Speed (PSI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "Ümumi IQ (FSIQ)", "ru": "Общий IQ (FSIQ)", "en": "Full Scale IQ (FSIQ)"}, "hint": {"az": "ümumi bal", "ru": "общий балл", "en": "composite"}}], "domains": [{"id": "d1", "title": {"az": "Söz ehtiyatı (VCI)", "ru": "Словарный запас (VCI)", "en": "Vocabulary (VCI)"}, "task": {"az": "Mütəxəssis uşağa söz deyir, uşaq onun mənasını izah edir. Məsələn, «alma nədir?»", "ru": "Специалист называет слово, ребёнок объясняет его значение. Например: «Что такое яблоко?»", "en": "The examiner says a word and the child explains its meaning. For example, \"What is an apple?\""}, "items": [{"id": "d1i1", "t": {"az": "Sözün mənasını izah edərkən doğru sözləri tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с подбором нужных слов при объяснении значения", "en": "Has difficulty finding the right words when explaining a meaning"}}, {"id": "d1i2", "t": {"az": "İzahı çox qısa və ya qeyri-dəqiq olur (məsələn, yalnız «yeyirik»)", "ru": "Объяснение слишком краткое или неточное (например, только «едим»)", "en": "Gives explanations that are too brief or imprecise (for example, only \"we eat it\")"}}, {"id": "d1i3", "t": {"az": "Yaşına uyğun gündəlik sözlərin mənasını bilmir", "ru": "Не знает значения обычных слов, соответствующих возрасту", "en": "Does not know the meaning of everyday words appropriate for age"}}]}, {"id": "d2", "title": {"az": "Oxşarlıqlar (VCI)", "ru": "Сходства (VCI)", "en": "Similarities (VCI)"}, "task": {"az": "İki əşya deyilir (məsələn, alma və banan), uşaq onların nəyə görə oxşar olduğunu söyləyir.", "ru": "Называются два предмета (например, яблоко и банан), ребёнок говорит, чем они похожи.", "en": "Two items are named (for example, apple and banana) and the child says how they are alike."}, "items": [{"id": "d2i1", "t": {"az": "İki əşyanın ümumi qrupunu (məsələn, «meyvə») tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с определением общей категории двух предметов (например, «фрукты»)", "en": "Has difficulty identifying the shared category of two items (for example, \"fruit\")"}}, {"id": "d2i2", "t": {"az": "Ortaq cəhət əvəzinə fərqi deyir və ya yalnız bir əşyanı təsvir edir", "ru": "Называет различие вместо общего признака или описывает только один предмет", "en": "Names a difference instead of a shared feature, or describes only one item"}}, {"id": "d2i3", "t": {"az": "Cavabı ümumi anlayışla deyil, konkret xüsusiyyətlə verir («hər ikisi sarıdır»)", "ru": "Отвечает конкретным признаком, а не обобщающим понятием («оба жёлтые»)", "en": "Answers with a concrete feature rather than a general concept (\"both are yellow\")"}}]}, {"id": "d3", "title": {"az": "Anlama (VCI)", "ru": "Понимание (VCI)", "en": "Comprehension (VCI)"}, "task": {"az": "Gündəlik həyat və sosial qaydalarla bağlı suallar verilir. Məsələn, «niyə əlləri yuyuruq?»", "ru": "Задаются вопросы о повседневной жизни и социальных правилах. Например: «Почему мы моем руки?»", "en": "Questions are asked about everyday life and social rules. For example, \"Why do we wash our hands?\""}, "items": [{"id": "d3i1", "t": {"az": "Qaydanın və ya hərəkətin səbəbini izah etməkdə çətinlik çəkir", "ru": "Испытывает трудности с объяснением причины правила или действия", "en": "Has difficulty explaining the reason for a rule or an action"}}, {"id": "d3i2", "t": {"az": "Sosial vəziyyətə uyğun cavab tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с подбором ответа, соответствующего социальной ситуации", "en": "Has difficulty finding an answer that fits the social situation"}}, {"id": "d3i3", "t": {"az": "Cavabı çox qısa olur və ya mövzudan kənara çıxır", "ru": "Ответ слишком краткий или не относится к теме", "en": "Gives answers that are too brief or off topic"}}]}, {"id": "d4", "title": {"az": "Blok dizayn (VSI)", "ru": "Кубики Коса (VSI)", "en": "Block Design (VSI)"}, "task": {"az": "Uşaq kublardan rəsmdəki naxışı qurur. Vaxt məhduddur, sekundomer lazımdır.", "ru": "Ребёнок собирает из кубиков узор по рисунку. Время ограничено, нужен секундомер.", "en": "The child builds the pattern shown in the picture with blocks. The task is timed; a stopwatch is needed."}, "items": [{"id": "d4i1", "t": {"az": "Rəsmdəki naxışı kublarla düzgün qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с построением узора из кубиков по рисунку", "en": "Has difficulty building the pattern from the picture with blocks"}}, {"id": "d4i2", "t": {"az": "Kubun üzünü və ya yerini səhv seçir, səhvi düzəltməkdə çətinlik çəkir", "ru": "Выбирает не ту грань или не то место для кубика и с трудом исправляет ошибку", "en": "Chooses the wrong block face or position and has difficulty correcting the error"}}, {"id": "d4i3", "t": {"az": "Vaxt məhdudiyyətində tapşırığı bitirməkdə çətinlik çəkir", "ru": "Испытывает трудности с завершением задания в пределах времени", "en": "Has difficulty completing the task within the time limit"}}]}, {"id": "d5", "title": {"az": "Vizual tapmaca (VSI)", "ru": "Зрительные пазлы (VSI)", "en": "Visual Puzzles (VSI)"}, "task": {"az": "Uşaq bir şəklə baxır və hansı hissələrin onu düzgün qurduğunu seçir.", "ru": "Ребёнок смотрит на картинку и выбирает части, из которых она собирается.", "en": "The child looks at a picture and selects the pieces that would make it."}, "items": [{"id": "d5i1", "t": {"az": "Hissələri zehnində birləşdirib bütöv şəkli təsəvvür etməkdə çətinlik çəkir", "ru": "Испытывает трудности с мысленным объединением частей в целое изображение", "en": "Has difficulty mentally combining pieces into a whole picture"}}, {"id": "d5i2", "t": {"az": "Çevrilmiş və ya fırlanmış hissələri tanımaqda çətinlik çəkir", "ru": "Испытывает трудности с узнаванием перевёрнутых или повёрнутых частей", "en": "Has difficulty recognizing flipped or rotated pieces"}}, {"id": "d5i3", "t": {"az": "Seçim edərkən tələsir və ya çox uzun tərəddüd edir", "ru": "Выбирает поспешно или слишком долго колеблется", "en": "Chooses hastily or hesitates for too long"}}]}, {"id": "d6", "title": {"az": "Matris mühakimə (FRI)", "ru": "Матрицы (FRI)", "en": "Matrix Reasoning (FRI)"}, "task": {"az": "Naxışlı şəkildə boş yer var, uşaq çatışmayan hissəni seçir.", "ru": "В узоре есть пропуск, ребёнок выбирает недостающую часть.", "en": "A pattern has a missing part and the child selects the piece that completes it."}, "items": [{"id": "d6i1", "t": {"az": "Naxışın qaydasını (rəng, forma, ölçü) görməkdə çətinlik çəkir", "ru": "Испытывает трудности с выявлением закономерности узора (цвет, форма, размер)", "en": "Has difficulty seeing the rule of the pattern (color, shape, size)"}}, {"id": "d6i2", "t": {"az": "Çatışmayan hissəni seçməkdə çətinlik çəkir", "ru": "Испытывает трудности с выбором недостающей части", "en": "Has difficulty selecting the missing piece"}}, {"id": "d6i3", "t": {"az": "Cavabı düşünmədən, təxmini seçir", "ru": "Выбирает ответ наугад, не обдумывая", "en": "Picks an answer at random without thinking it through"}}]}, {"id": "d7", "title": {"az": "Kəmiyyət mühakimə (FRI)", "ru": "Количественное рассуждение (FRI)", "en": "Quantitative Reasoning (FRI)"}, "task": {"az": "Uşağa kublar və ya say kartları göstərilir: «hansı qrupda çoxdur?», «bərabər olmaq üçün neçə kub əlavə etmək lazımdır?» kimi sadə müqayisələr və 2, 4, 6, … kimi say sırasının davamı istənir.", "ru": "Ребёнку показывают кубики или карточки с числами: простые сравнения вроде «где больше?», «сколько кубиков добавить, чтобы стало поровну?» и продолжение ряда 2, 4, 6, …", "en": "The child is shown blocks or number cards: simple comparisons such as \"which group has more?\" and \"how many blocks must be added to make them equal?\", and is asked to continue a series such as 2, 4, 6, …"}, "items": [{"id": "d7i1", "t": {"az": "İki qrupu say baxımından müqayisə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с количественным сравнением двух групп", "en": "Has difficulty comparing two groups by quantity"}}, {"id": "d7i2", "t": {"az": "Say sırasının qaydasını tapıb davam etdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с выявлением закономерности числового ряда и его продолжением", "en": "Has difficulty finding the rule of a number series and continuing it"}}, {"id": "d7i3", "t": {"az": "Tapşırıq bir az dəyişəndə yeni üsul tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с поиском нового способа, когда задание немного меняется", "en": "Has difficulty finding a new approach when the task changes slightly"}}]}, {"id": "d8", "title": {"az": "Rəqəm ardıcıllığı (WMI)", "ru": "Повторение цифр (WMI)", "en": "Digit Span (WMI)"}, "task": {"az": "Mütəxəssis rəqəmləri bir-bir deyir, uşaq əvvəl eşitdiyi kimi, sonra tərsinə və sıralayaraq təkrarlayır.", "ru": "Специалист называет цифры по одной, ребёнок повторяет их так, как услышал, затем в обратном порядке и в порядке возрастания.", "en": "The examiner reads digits one at a time and the child repeats them as heard, then in reverse order and in sequence order."}, "items": [{"id": "d8i1", "t": {"az": "Eşitdiyi rəqəmləri eyni ardıcıllıqla təkrarlamaqda çətinlik çəkir", "ru": "Испытывает трудности с повторением услышанных цифр в том же порядке", "en": "Has difficulty repeating the digits heard in the same order"}}, {"id": "d8i2", "t": {"az": "Rəqəmləri tərs sırada və ya sıralayaraq deməkdə çətinlik çəkir", "ru": "Испытывает трудности с называнием цифр в обратном порядке или по возрастанию", "en": "Has difficulty saying digits in reverse order or in ascending order"}}, {"id": "d8i3", "t": {"az": "Rəqəmlərin sayı artanda ardıcıllığı itirir", "ru": "Теряет последовательность, когда количество цифр увеличивается", "en": "Loses the sequence as the number of digits increases"}}]}, {"id": "d9", "title": {"az": "Şəkil ardıcıllığı (WMI)", "ru": "Запоминание картинок (WMI)", "en": "Picture Span (WMI)"}, "task": {"az": "Uşağa bir neçə saniyə şəkillər göstərilir, sonra o, həmin şəkilləri cavab səhifəsindən eyni sıra ilə seçir.", "ru": "Ребёнку на несколько секунд показывают картинки, затем он выбирает их на странице ответов в том же порядке.", "en": "The child is shown pictures for a few seconds and then selects them from the response page in the same order."}, "items": [{"id": "d9i1", "t": {"az": "Şəkillərin sırasını yadda saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с запоминанием порядка картинок", "en": "Has difficulty remembering the order of the pictures"}}, {"id": "d9i2", "t": {"az": "Şəkillərin sayı artanda sıranı qarışdırır", "ru": "Путает порядок, когда количество картинок увеличивается", "en": "Mixes up the order as the number of pictures increases"}}, {"id": "d9i3", "t": {"az": "Cavab səhifəsində artıq şəkillər olanda doğrusunu seçməkdə çətinlik çəkir", "ru": "Испытывает трудности с выбором правильных картинок, когда на странице ответов есть лишние", "en": "Has difficulty choosing the correct pictures when the response page contains extra ones"}}]}, {"id": "d10", "title": {"az": "Kodlaşdırma (PSI)", "ru": "Шифровка (PSI)", "en": "Coding (PSI)"}, "task": {"az": "Uşaq vaxt məhdud olduqda hər rəqəmə uyğun simvolu cədvələ yazır. Qələm və sekundomer lazımdır.", "ru": "Ребёнок вписывает в таблицу символ, соответствующий каждой цифре, с ограничением по времени. Нужны карандаш и секундомер.", "en": "Within a time limit, the child writes in the table the symbol that matches each digit. A pencil and a stopwatch are needed."}, "items": [{"id": "d10i1", "t": {"az": "Simvolları düzgün və səliqəli köçürməkdə çətinlik çəkir", "ru": "Испытывает трудности с правильным и аккуратным копированием символов", "en": "Has difficulty copying symbols accurately and neatly"}}, {"id": "d10i2", "t": {"az": "Tapşırığı vaxtında bitirməkdə çətinlik çəkir", "ru": "Испытывает трудности с завершением задания в отведённое время", "en": "Has difficulty finishing the task in the allotted time"}}, {"id": "d10i3", "t": {"az": "Tempi sabit saxlamaqda çətinlik çəkir: əvvəl sürətli, sonra yavaşlayır", "ru": "Испытывает трудности с поддержанием постоянного темпа: сначала быстро, затем замедляется", "en": "Has difficulty keeping a steady pace: fast at first, then slows down"}}]}, {"id": "d11", "title": {"az": "Simvol axtarışı (PSI)", "ru": "Поиск символов (PSI)", "en": "Symbol Search (PSI)"}, "task": {"az": "Uşaq hədəf simvolun cərgədə olub-olmadığını vaxt məhdud olduqda işarələyir.", "ru": "Ребёнок отмечает, есть ли целевой символ в ряду, с ограничением по времени.", "en": "Within a time limit, the child marks whether the target symbol appears in the row."}, "items": [{"id": "d11i1", "t": {"az": "Hədəf simvolu cərgədə tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с поиском целевого символа в ряду", "en": "Has difficulty finding the target symbol in the row"}}, {"id": "d11i2", "t": {"az": "Tələsəndə səhv işarələyir", "ru": "Ошибается в отметках, когда торопится", "en": "Makes marking errors when rushing"}}, {"id": "d11i3", "t": {"az": "Tapşırıq davam etdikcə diqqətini saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением внимания по ходу задания", "en": "Has difficulty sustaining attention as the task continues"}}]}, {"id": "d12", "title": {"az": "Əqli hesab", "ru": "Устный счёт", "en": "Arithmetic"}, "task": {"az": "Mütəxəssis hesab məsələsini səslə oxuyur, uşaq kağız-qələmsiz zehnində həll edir.", "ru": "Специалист читает вслух арифметическую задачу, ребёнок решает её в уме, без бумаги и карандаша.", "en": "The examiner reads an arithmetic problem aloud and the child solves it mentally, without paper or pencil."}, "items": [{"id": "d12i1", "t": {"az": "Məsələni eşidib mənasını başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием смысла задачи на слух", "en": "Has difficulty understanding the meaning of the problem when heard"}}, {"id": "d12i2", "t": {"az": "Rəqəmləri yadda saxlayıb zehnində hesablamaqda çətinlik çəkir", "ru": "Испытывает трудности с удержанием чисел в памяти и вычислением в уме", "en": "Has difficulty holding numbers in mind and calculating mentally"}}, {"id": "d12i3", "t": {"az": "Vaxt məhdudiyyətində cavab verməkdə çətinlik çəkir", "ru": "Испытывает трудности с ответом в пределах времени", "en": "Has difficulty answering within the time limit"}}]}, {"id": "d13", "title": {"az": "Eşitmə işlək yaddaşı", "ru": "Слуховая рабочая память", "en": "Letter-Number Sequencing"}, "task": {"az": "Mütəxəssis qarışıq rəqəm və hərflər deyir, uşaq onları müəyyən qaydada (əvvəl rəqəmlər, sonra hərflər) yenidən sıralayır.", "ru": "Специалист называет вперемешку цифры и буквы, ребёнок переставляет их в заданном порядке (сначала цифры, затем буквы).", "en": "The examiner reads a mixed series of digits and letters and the child reorders them in a set sequence (digits first, then letters)."}, "items": [{"id": "d13i1", "t": {"az": "Eşitdiyi məlumatı qaydaya salıb yenidən düzməkdə çətinlik çəkir", "ru": "Испытывает трудности с упорядочением и перестановкой услышанной информации", "en": "Has difficulty organizing and reordering the information heard"}}, {"id": "d13i2", "t": {"az": "Uzun göstərişi bir dəfə eşidib yadda saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с запоминанием длинной инструкции после однократного предъявления", "en": "Has difficulty remembering a long instruction after hearing it once"}}, {"id": "d13i3", "t": {"az": "Tapşırıq davam etdikcə diqqətini saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением внимания по ходу задания", "en": "Has difficulty sustaining attention as the task continues"}}]}, {"id": "d14", "title": {"az": "Test davranışı (bütün seansa aid)", "ru": "Поведение при тестировании (вся сессия)", "en": "Test Behavior (whole session)"}, "task": {"az": "Ayrıca tapşırıq yoxdur. Mütəxəssis seans boyu uşağın davranışına baxır.", "ru": "Отдельного задания нет. Специалист наблюдает за поведением ребёнка на протяжении всей сессии.", "en": "There is no separate task. The examiner observes the child's behavior throughout the session."}, "items": [{"id": "d14i1", "t": {"az": "Tapşırıqlara cəhd etməkdə və davam etməkdə çətinlik çəkir", "ru": "Испытывает трудности с началом выполнения заданий и их продолжением", "en": "Has difficulty attempting tasks and persisting with them"}}, {"id": "d14i2", "t": {"az": "Çətin tapşırıqda əsəbiləşməni və ya imtinanı idarə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с управлением раздражением или отказом при трудном задании", "en": "Has difficulty managing frustration or refusal on a hard task"}}, {"id": "d14i3", "t": {"az": "Göstərişi dinləməkdə və ona əməl etməkdə çətinlik çəkir", "ru": "Испытывает трудности с выслушиванием инструкции и следованием ей", "en": "Has difficulty listening to instructions and following them"}}]}], "specialist": [{"az": "İndekslər arasındakı fərqi (profil) şərh edin, təkcə ümumi IQ-ya baxmayın.", "ru": "Интерпретируйте различия между индексами (профиль), а не только общий IQ.", "en": "Interpret the differences between indices (the profile), not just Full Scale IQ."}, {"az": "Zəif indeksləri öyrənmə dəstəyi planına çevirin.", "ru": "Превратите слабые индексы в план учебной поддержки.", "en": "Translate weak indices into a learning-support plan."}, {"az": "Nəticələri məktəb və ailə müşahidələri ilə birləşdirin.", "ru": "Соедините результаты с наблюдениями школы и семьи.", "en": "Combine results with school and family observations."}], "parentIntro": {"az": "Bu test uşağınızın necə öyrəndiyini göstərir — 'ağıllı/ağılsız' deyil, güclü və dəstək lazım olan sahələri.", "ru": "Этот тест показывает, как ваш ребёнок учится — не «умный/неумный», а сильные стороны и зоны поддержки.", "en": "This test shows how your child learns — not 'smart/not smart', but strengths and areas needing support."}, "parentTips": [{"az": "Güclü sahələri tərifləyin və onlara söykənərək yeni şeylər öyrədin.", "ru": "Хвалите сильные стороны и через них обучайте новому.", "en": "Praise strengths and teach new things by building on them."}, {"az": "Tapşırıqları kiçik addımlara bölün.", "ru": "Разбивайте задания на маленькие шаги.", "en": "Break tasks into small steps."}, {"az": "Yaddaş üçün şəkil və rəng kimi vizual ipucları istifadə edin.", "ru": "Для памяти используйте визуальные подсказки — картинки, цвета.", "en": "Use visual cues like pictures and colors to aid memory."}], "games": [{"az": "Yaddaş kartları: cüt şəkilləri tapmaq işlək yaddaşı gücləndirir.", "ru": "Карточки памяти: поиск пар укрепляет рабочую память.", "en": "Memory cards: finding pairs strengthens working memory."}, {"az": "Tapmaca və naxış davam etdirmə oyunları məntiqi inkişaf etdirir.", "ru": "Пазлы и продолжение узоров развивают логику.", "en": "Puzzles and pattern-continuation games develop reasoning."}, {"az": "'Nə dəyişdi?' oyunu: əşyaları gizlədib soruşun — diqqəti gücləndirir.", "ru": "Игра «что изменилось?»: прячьте предметы и спрашивайте — развивает внимание.", "en": "'What changed?' game: hide items and ask — builds attention."}]}, "vineland3": {"id": "vineland3", "name": "Vineland-3", "full": {"az": "Vineland Adaptiv Davranış Şkalaları, 3-cü nəşr", "ru": "Шкалы адаптивного поведения Вайнленд, 3-е изд.", "en": "Vineland Adaptive Behavior Scales, 3rd ed."}, "age": {"az": "Doğuşdan böyük yaşlara qədər", "ru": "От рождения до взрослого возраста", "en": "Birth through adulthood"}, "summary": {"az": "Uşağın gündəlik həyatda real funksional bacarıqlarını — adaptiv davranışı — ölçür. Bilik deyil, gündəlik tətbiqi qiymətləndirir.", "ru": "Измеряет реальные функциональные навыки ребёнка в повседневной жизни — адаптивное поведение. Оценивает не знания, а применение.", "en": "Measures the child's real-world functional skills in daily life — adaptive behavior. Assesses application, not knowledge."}, "advantages": [{"az": "Gündəlik real bacarıqlara fokuslanır", "ru": "Сфокусирован на реальных повседневных навыках", "en": "Focuses on real daily skills"}, {"az": "Müdaxilə hədəfləri qoymağa kömək edir", "ru": "Помогает ставить цели вмешательства", "en": "Helps set intervention targets"}, {"az": "İrəliləyişi izləmək üçün əla", "ru": "Отлично подходит для отслеживания прогресса", "en": "Excellent for tracking progress"}, {"az": "Müxtəlif yaş və səviyyələrə uyğun", "ru": "Подходит для разных возрастов и уровней", "en": "Suitable for varied ages and levels"}], "instruction": {"howto": [{"az": "Uşağı yaxşı tanıyan valideyn/baxıcı ilə doldurun.", "ru": "Заполняйте с родителем/опекуном, хорошо знающим ребёнка.", "en": "Complete with a parent/caregiver who knows the child well."}, {"az": "Uşağın 'edə bildiyi' deyil, 'adətən etdiyi' davranışı qeyd edin.", "ru": "Отмечайте то, что ребёнок «обычно делает», а не «может».", "en": "Record what the child 'usually does', not what they 'can do'."}, {"az": "Bütün sahələri ardıcıl əhatə edin.", "ru": "Последовательно охватите все области.", "en": "Cover all domains systematically."}], "methods": [{"az": "Müsahibə və ya valideyn anketi formatı", "ru": "Формат интервью или анкеты для родителя", "en": "Interview or parent questionnaire format"}, {"az": "Müşahidə ilə dəstəklənən hesabat", "ru": "Отчёт, подкреплённый наблюдением", "en": "Report supported by observation"}], "scoring": [{"az": "Bənd cavabları sahə üzrə standart ballara çevrilir.", "ru": "Ответы по пунктам переводятся в стандартные баллы по областям.", "en": "Item responses convert to domain standard scores."}, {"az": "Adaptiv Davranış Kompoziti yalnız rəsmi norma ilə hesablanır.", "ru": "Композит адаптивного поведения рассчитывается только по официальным нормам.", "en": "The Adaptive Behavior Composite is computed only with official norms."}]}, "official": [{"label": {"az": "Ünsiyyət sahəsi balı", "ru": "Балл области коммуникации", "en": "Communication domain score"}, "hint": {"az": "standart bal", "ru": "стандартный балл", "en": "standard score"}}, {"label": {"az": "Gündəlik yaşam balı", "ru": "Балл повседневных навыков", "en": "Daily Living score"}, "hint": {"az": "standart bal", "ru": "стандартный балл", "en": "standard score"}}, {"label": {"az": "Sosiallaşma balı", "ru": "Балл социализации", "en": "Socialization score"}, "hint": {"az": "standart bal", "ru": "стандартный балл", "en": "standard score"}}, {"label": {"az": "Motor bacarıqlar balı", "ru": "Балл моторики", "en": "Motor Skills score"}, "hint": {"az": "varsa", "ru": "если применимо", "en": "if applicable"}}, {"label": {"az": "Adaptiv Davranış Kompoziti (ABC)", "ru": "Композит адаптивного поведения (ABC)", "en": "Adaptive Behavior Composite (ABC)"}, "hint": {"az": "ümumi bal", "ru": "общий балл", "en": "composite"}}], "domains": [{"id": "d1", "title": {"az": "Ünsiyyət — reseptiv (anlama)", "ru": "Коммуникация: рецептивная (понимание)", "en": "Communication: Receptive"}, "task": {"az": "Valideynə sual: uşaq sadə göstərişləri («su gətir») və sualları başa düşür? Uzun izahı izləyir?", "ru": "Вопрос родителю: понимает ли ребёнок простые просьбы («принеси воды») и вопросы? Следит ли за длинным объяснением?", "en": "Question to the parent: does the child understand simple requests (\"bring water\") and questions? Can the child follow a long explanation?"}, "items": [{"id": "d1i1", "t": {"az": "Sadə göstəriş və sualları başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием простых инструкций и вопросов", "en": "Has difficulty understanding simple instructions and questions"}}, {"id": "d1i2", "t": {"az": "Uzun və ya mürəkkəb izahı izləməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием длинных или сложных объяснений", "en": "Has difficulty following long or complex explanations"}}, {"id": "d1i3", "t": {"az": "Eşitdiyinə uyğun reaksiya verməkdə çətinlik çəkir", "ru": "Испытывает трудности с адекватной реакцией на услышанное", "en": "Has difficulty responding appropriately to what is heard"}}]}, {"id": "d2", "title": {"az": "Ünsiyyət — ekspressiv (danışma)", "ru": "Коммуникация: экспрессивная (речь)", "en": "Communication: Expressive"}, "task": {"az": "Valideynə sual: istəyini necə bildirir? Gün ərzində nə olduğunu danışıb izah edir?", "ru": "Вопрос родителю: как ребёнок выражает желания? Рассказывает ли, что было в течение дня?", "en": "Question to the parent: how does the child express wishes? Does the child tell what happened during the day?"}, "items": [{"id": "d2i1", "t": {"az": "İstək və ehtiyaclarını ifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с выражением желаний и потребностей", "en": "Has difficulty expressing wants and needs"}}, {"id": "d2i2", "t": {"az": "Söhbətdə qarşılıqlı iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в беседе", "en": "Has difficulty taking part in conversation"}}, {"id": "d2i3", "t": {"az": "Hadisələri danışıb təsvir etməkdə çətinlik çəkir", "ru": "Испытывает трудности с рассказом о событиях и их описанием", "en": "Has difficulty telling about and describing events"}}]}, {"id": "d3", "title": {"az": "Ünsiyyət — yazılı (oxu və yazı)", "ru": "Коммуникация: письменная (чтение и письмо)", "en": "Communication: Written"}, "task": {"az": "Valideynə sual: hərfləri tanıyır, oxuyur, öz adını yazır? Yazılı tapşırığı başa düşür?", "ru": "Вопрос родителю: узнаёт ли ребёнок буквы, читает ли, пишет ли своё имя? Понимает ли письменное задание?", "en": "Question to the parent: does the child recognize letters, read, and write his or her own name? Does the child understand written instructions?"}, "items": [{"id": "d3i1", "t": {"az": "Yaşına uyğun oxumaqda çətinlik çəkir", "ru": "Испытывает трудности с чтением, соответствующим возрасту", "en": "Has difficulty reading at an age-appropriate level"}}, {"id": "d3i2", "t": {"az": "Hərf və yazı bacarıqlarında çətinlik çəkir", "ru": "Испытывает трудности с навыками букв и письма", "en": "Has difficulty with letter and writing skills"}}, {"id": "d3i3", "t": {"az": "Yazılı təlimatı başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием письменных инструкций", "en": "Has difficulty understanding written instructions"}}]}, {"id": "d4", "title": {"az": "Gündəlik — şəxsi qulluq", "ru": "Повседневные навыки: личная гигиена и уход", "en": "Daily Living Skills: Personal"}, "task": {"az": "Valideynə sual: özü geyinir, yeyir, əl-üzünü yuyur, tualetə gedir?", "ru": "Вопрос родителю: одевается ли ребёнок сам, ест, умывается, ходит в туалет?", "en": "Question to the parent: does the child dress, eat, wash hands and face, and use the toilet independently?"}, "items": [{"id": "d4i1", "t": {"az": "Geyinmə, yemək və gigiyena bacarıqlarında çətinlik çəkir", "ru": "Испытывает трудности с навыками одевания, приёма пищи и гигиены", "en": "Has difficulty with dressing, eating, and hygiene skills"}}, {"id": "d4i2", "t": {"az": "Tualet bacarıqlarında çətinlik çəkir", "ru": "Испытывает трудности с навыками пользования туалетом", "en": "Has difficulty with toileting skills"}}, {"id": "d4i3", "t": {"az": "Şəxsi əşyalarına qulluq etməkdə çətinlik çəkir", "ru": "Испытывает трудности с уходом за личными вещами", "en": "Has difficulty looking after personal belongings"}}]}, {"id": "d5", "title": {"az": "Gündəlik — ev və məişət", "ru": "Повседневные навыки: дом и быт", "en": "Daily Living Skills: Domestic"}, "task": {"az": "Valideynə sual: evdə hansı işlərə kömək edir (süfrə qurmaq, oyuncaqları yığmaq)?", "ru": "Вопрос родителю: в каких домашних делах ребёнок помогает (накрывает на стол, убирает игрушки)?", "en": "Question to the parent: what household tasks does the child help with (setting the table, putting away toys)?"}, "items": [{"id": "d5i1", "t": {"az": "Sadə ev işlərində iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в простых домашних делах", "en": "Has difficulty taking part in simple household tasks"}}, {"id": "d5i2", "t": {"az": "Əşyaları öz yerinə qoymaqda çətinlik çəkir", "ru": "Испытывает трудности с тем, чтобы класть вещи на место", "en": "Has difficulty putting things away"}}, {"id": "d5i3", "t": {"az": "Sadə hazırlıq işlərinə kömək etməkdə çətinlik çəkir", "ru": "Испытывает трудности с помощью в простой подготовке (например, к приёму пищи)", "en": "Has difficulty helping with simple preparations (for example, for meals)"}}]}, {"id": "d6", "title": {"az": "Gündəlik — icma", "ru": "Повседневные навыки: социум", "en": "Daily Living Skills: Community"}, "task": {"az": "Valideynə sual: pulu və saatı yaşına görə başa düşür? Küçədə təhlükəsizlik qaydalarına əməl edir? Mağaza, nəqliyyatda necə davranır?", "ru": "Вопрос родителю: понимает ли ребёнок деньги и время в соответствии с возрастом? Соблюдает ли правила безопасности на улице? Как ведёт себя в магазине и транспорте?", "en": "Question to the parent: does the child understand money and time for his or her age? Does the child follow safety rules outdoors? How does the child behave in shops and on public transport?"}, "items": [{"id": "d6i1", "t": {"az": "Pul və vaxt anlayışını (yaşa uyğun) başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием денег и времени (в соответствии с возрастом)", "en": "Has difficulty understanding money and time (for age)"}}, {"id": "d6i2", "t": {"az": "Təhlükəsizlik qaydalarını bilməkdə və tətbiq etməkdə çətinlik çəkir", "ru": "Испытывает трудности с усвоением и применением правил безопасности", "en": "Has difficulty learning and applying safety rules"}}, {"id": "d6i3", "t": {"az": "İctimai yerlərdə uyğun davranmaqda çətinlik çəkir", "ru": "Испытывает трудности с адекватным поведением в общественных местах", "en": "Has difficulty behaving appropriately in public places"}}]}, {"id": "d7", "title": {"az": "Sosiallaşma — münasibətlər", "ru": "Социализация: межличностные отношения", "en": "Socialization: Interpersonal Relationships"}, "task": {"az": "Valideynə sual: tanışlarla və yaşıdları ilə münasibət qura bilir? Başqasının hissini tanıyır? Dostu var?", "ru": "Вопрос родителю: может ли ребёнок выстраивать отношения со знакомыми и сверстниками? Распознаёт ли чувства других? Есть ли у него друг?", "en": "Question to the parent: can the child build relationships with familiar people and peers? Does the child recognize others' feelings? Does the child have a friend?"}, "items": [{"id": "d7i1", "t": {"az": "Başqaları ilə münasibət qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с построением отношений с другими людьми", "en": "Has difficulty building relationships with others"}}, {"id": "d7i2", "t": {"az": "Başqasının emosiyasını tanımaqda çətinlik çəkir", "ru": "Испытывает трудности с распознаванием эмоций других людей", "en": "Has difficulty recognizing other people's emotions"}}, {"id": "d7i3", "t": {"az": "Dostluğu saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с поддержанием дружбы", "en": "Has difficulty maintaining friendships"}}]}, {"id": "d8", "title": {"az": "Sosiallaşma — oyun və asudə vaxt", "ru": "Социализация: игра и досуг", "en": "Socialization: Play and Leisure Time"}, "task": {"az": "Valideynə sual: uşaqlarla oynayanda növbə gözləyir, oyuncağı bölüşür? Qrup fəaliyyətində iştirak edir?", "ru": "Вопрос родителю: ждёт ли ребёнок очереди, делится ли игрушками в игре с другими детьми? Участвует ли в групповых занятиях?", "en": "Question to the parent: does the child take turns and share toys when playing with other children? Does the child join group activities?"}, "items": [{"id": "d8i1", "t": {"az": "Oyun və asudə vaxtı başqası ilə bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с совместной игрой и проведением досуга с другими", "en": "Has difficulty sharing play and leisure with others"}}, {"id": "d8i2", "t": {"az": "Növbə gözləməkdə və bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с ожиданием очереди и с тем, чтобы делиться", "en": "Has difficulty taking turns and sharing"}}, {"id": "d8i3", "t": {"az": "Qrup fəaliyyətində iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в групповых занятиях", "en": "Has difficulty taking part in group activities"}}]}, {"id": "d9", "title": {"az": "Sosiallaşma — uyğunlaşma", "ru": "Социализация: навыки совладания", "en": "Socialization: Coping Skills"}, "task": {"az": "Valideynə sual: qaydalara əməl edir? Qəzəbləndikdə özünü idarə edir? Xətasını görəndə üzr istəyir?", "ru": "Вопрос родителю: соблюдает ли ребёнок правила? Справляется ли с собой, когда сердится? Извиняется ли, увидев свою ошибку?", "en": "Question to the parent: does the child follow rules? Does the child control himself or herself when angry? Does the child apologize on seeing a mistake?"}, "items": [{"id": "d9i1", "t": {"az": "Sosial qaydalara uyğunlaşmaqda çətinlik çəkir", "ru": "Испытывает трудности с приспособлением к социальным правилам", "en": "Has difficulty adapting to social rules"}}, {"id": "d9i2", "t": {"az": "Emosiyalarını idarə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с управлением эмоциями", "en": "Has difficulty managing emotions"}}, {"id": "d9i3", "t": {"az": "Məsuliyyət daşımaqda və üzr istəməkdə çətinlik çəkir", "ru": "Испытывает трудности с принятием ответственности и принесением извинений", "en": "Has difficulty taking responsibility and apologizing"}}]}, {"id": "d10", "title": {"az": "Motor bacarıqlar — iri", "ru": "Моторные навыки: крупная моторика", "en": "Motor Skills: Gross"}, "task": {"az": "Valideynə sual: qaçır, tullanır, pilləkən çıxır, topla oynayır? Tez-tez yıxılır?", "ru": "Вопрос родителю: бегает ли ребёнок, прыгает, поднимается по лестнице, играет в мяч? Часто ли падает?", "en": "Question to the parent: does the child run, jump, climb stairs, and play ball? Does the child fall often?"}, "items": [{"id": "d10i1", "t": {"az": "Qaçma, tullanma və tarazlıqda çətinlik çəkir", "ru": "Испытывает трудности с бегом, прыжками и равновесием", "en": "Has difficulty with running, jumping, and balance"}}, {"id": "d10i2", "t": {"az": "Hərəkətlərinin koordinasiyasında çətinlik çəkir", "ru": "Испытывает трудности с координацией движений", "en": "Has difficulty coordinating movements"}}, {"id": "d10i3", "t": {"az": "Pilləkən və maneələri keçməkdə çətinlik çəkir", "ru": "Испытывает трудности с преодолением лестниц и препятствий", "en": "Has difficulty managing stairs and obstacles"}}]}, {"id": "d11", "title": {"az": "Motor bacarıqlar — incə", "ru": "Моторные навыки: мелкая моторика", "en": "Motor Skills: Fine"}, "task": {"az": "Valideynə sual: qələm tutur, düymə bağlayır, qayçı ilə kəsir, kiçik əşyaları götürür?", "ru": "Вопрос родителю: держит ли ребёнок карандаш, застёгивает ли пуговицы, режет ли ножницами, берёт ли мелкие предметы?", "en": "Question to the parent: does the child hold a pencil, fasten buttons, cut with scissors, and pick up small objects?"}, "items": [{"id": "d11i1", "t": {"az": "Qələm, düymə və ya qayçıdan istifadədə çətinlik çəkir", "ru": "Испытывает трудности с использованием карандаша, пуговиц или ножниц", "en": "Has difficulty using a pencil, buttons, or scissors"}}, {"id": "d11i2", "t": {"az": "Əl-göz koordinasiyasında çətinlik çəkir", "ru": "Испытывает трудности с координацией глаз и рук", "en": "Has difficulty with eye-hand coordination"}}, {"id": "d11i3", "t": {"az": "Kiçik əşyaları idarə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с манипулированием мелкими предметами", "en": "Has difficulty manipulating small objects"}}]}, {"id": "d12", "title": {"az": "Problemli davranış — daxilə yönəlmiş", "ru": "Дезадаптивное поведение: интернализированное", "en": "Maladaptive Behavior: Internalizing"}, "task": {"az": "Valideynə sual: uşaq qapanır, çox narahat olur, qorxur, kədərli görünür? Bu, gündəlik işlərinə mane olur?", "ru": "Вопрос родителю: замыкается ли ребёнок в себе, сильно тревожится, боится, выглядит печальным? Мешает ли это повседневной деятельности?", "en": "Question to the parent: does the child withdraw, worry a great deal, seem fearful or sad? Does this interfere with daily activities?"}, "items": [{"id": "d12i1", "t": {"az": "Qapanır və ya çox narahat olur", "ru": "Замыкается в себе или сильно тревожится", "en": "Withdraws or is very anxious"}}, {"id": "d12i2", "t": {"az": "Kədər və ya qorxu əlamətləri göstərir", "ru": "Проявляет признаки печали или страха", "en": "Shows signs of sadness or fear"}}, {"id": "d12i3", "t": {"az": "Bu hallar gündəlik fəaliyyətinə mane olur", "ru": "Эти состояния мешают повседневной деятельности", "en": "These states interfere with daily activities"}}]}, {"id": "d13", "title": {"az": "Problemli davranış — xaricə yönəlmiş", "ru": "Дезадаптивное поведение: экстернализированное", "en": "Maladaptive Behavior: Externalizing"}, "task": {"az": "Valideynə sual: vurur, dişləyir, qışqırır, ani hərəkət edir? Qaydalara qarşı çıxır?", "ru": "Вопрос родителю: бьёт ли ребёнок, кусается, кричит, действует импульсивно? Противится ли правилам?", "en": "Question to the parent: does the child hit, bite, shout, or act impulsively? Does the child oppose rules?"}, "items": [{"id": "d13i1", "t": {"az": "Aqressiv və ya impulsiv davranış göstərir", "ru": "Проявляет агрессивное или импульсивное поведение", "en": "Shows aggressive or impulsive behavior"}}, {"id": "d13i2", "t": {"az": "Qaydalara qarşı çıxır", "ru": "Противится правилам", "en": "Opposes rules"}}, {"id": "d13i3", "t": {"az": "Fəaliyyətə mane olan davranış göstərir", "ru": "Проявляет поведение, мешающее деятельности", "en": "Shows behavior that disrupts activities"}}]}], "specialist": [{"az": "Ən aşağı sahələri ilkin müdaxilə hədəfi seçin.", "ru": "Выберите самые слабые области как первичные цели вмешательства.", "en": "Select the lowest domains as primary intervention targets."}, {"az": "Bacarıqları kiçik, ölçülə bilən addımlara bölün.", "ru": "Разбейте навыки на маленькие измеримые шаги.", "en": "Break skills into small, measurable steps."}, {"az": "3–6  aydan bir təkrar ölçməklə irəliləyişi izləyin.", "ru": "Отслеживайте прогресс повторной оценкой каждые 3–6 мес.", "en": "Track progress with re-assessment every 3–6 months."}], "parentIntro": {"az": "Bu sahələr uşağınızın gündəlik müstəqilliyini göstərir. Kiçik gündəlik təcrübə böyük fərq yaradır.", "ru": "Эти области показывают повседневную самостоятельность ребёнка. Маленькая ежедневная практика даёт большую разницу.", "en": "These areas show your child's daily independence. Small daily practice makes a big difference."}, "parentTips": [{"az": "Gündəlik işləri (geyinmə, süfrə) birlikdə addım-addım öyrədin.", "ru": "Учите повседневным делам (одевание, стол) вместе, шаг за шагом.", "en": "Teach daily tasks (dressing, table) together, step by step."}, {"az": "Bacarığı göstərib sonra uşağa cəhd imkanı verin.", "ru": "Покажите навык, затем дайте ребёнку попробовать.", "en": "Demonstrate the skill, then let the child try."}, {"az": "Hər kiçik uğuru tərifləyin — təkrar motivasiya gətirir.", "ru": "Хвалите каждый маленький успех — повторение даёт мотивацию.", "en": "Praise every small success — repetition builds motivation."}], "games": [{"az": "'Köməkçi' oyunu: süfrə düzmək, paltar qatlamaq kimi real işlər.", "ru": "Игра «помощник»: реальные дела — накрыть стол, сложить одежду.", "en": "'Helper' game: real tasks like setting the table, folding clothes."}, {"az": "Geyinmə yarışı: düymə və zəncirləri əyləncəli şəkildə məşq edin.", "ru": "Гонка одевания: тренируйте пуговицы и молнии играючи.", "en": "Dressing race: practice buttons and zippers playfully."}, {"az": "Rollu oyun (mağaza, həkim) sosial bacarıqları gücləndirir.", "ru": "Ролевая игра (магазин, доктор) укрепляет социальные навыки.", "en": "Role-play (shop, doctor) strengthens social skills."}]}, "leiter3": {"id": "leiter3", "name": "Leiter-3", "full": {"az": "Leiter Beynəlxalq Performans Şkalası, 3-cü nəşr", "ru": "Международная шкала производительности Лейтер, 3-е изд.", "en": "Leiter International Performance Scale, 3rd ed."}, "age": {"az": "3 yaşdan böyük (uşaq və böyüklər)", "ru": "От 3 лет (дети и взрослые)", "en": "Ages 3 and up (children and adults)"}, "summary": {"az": "Tamamilə qeyri-verbal idrak testi — danışıq tələb etmir. Dil və ya eşitmə çətinliyi olan uşaqlar üçün ideal idrak qiymətləndirməsidir.", "ru": "Полностью невербальный когнитивный тест — не требует речи. Идеален для детей с трудностями речи или слуха.", "en": "A fully nonverbal cognitive test — requires no speech. Ideal cognitive assessment for children with speech or hearing difficulties."}, "advantages": [{"az": "Danışıq tələb etmir", "ru": "Не требует речи", "en": "Requires no speech"}, {"az": "Dil maneəsini aradan qaldırır", "ru": "Устраняет языковой барьер", "en": "Removes the language barrier"}, {"az": "Eşitmə çətinliyi olanlar üçün uyğundur", "ru": "Подходит при трудностях слуха", "en": "Suitable for those with hearing difficulties"}, {"az": "Saf idrak qabiliyyətini açır", "ru": "Раскрывает чистую когнитивную способность", "en": "Reveals pure cognitive ability"}], "instruction": {"howto": [{"az": "Göstəriş və nümunələri jest və modelləşdirmə ilə verin.", "ru": "Давайте инструкции жестами и показом.", "en": "Give instructions through gesture and modeling."}, {"az": "Sakit mühitdə, vizual material ilə təkbətək işləyin.", "ru": "Работайте наедине в тихой среде с визуальным материалом.", "en": "Work one-on-one in a quiet setting with visual material."}, {"az": "Uşağın yanaşma tərzini və səbrini müşahidə edin.", "ru": "Наблюдайте подход и терпение ребёнка.", "en": "Observe the child's approach and patience."}], "methods": [{"az": "Vizual uyğunlaşdırma və ardıcıllıq tapşırıqları", "ru": "Зрительное сопоставление и задания на последовательность", "en": "Visual matching and sequencing tasks"}, {"az": "Jestlə verilən qeyri-verbal göstərişlər", "ru": "Невербальные инструкции жестами", "en": "Nonverbal gesture-based instructions"}], "scoring": [{"az": "Performans xam balları normaya görə çevrilir.", "ru": "Сырые баллы производительности переводятся по нормам.", "en": "Performance raw scores convert per norms."}, {"az": "IQ ekvivalenti yalnız rəsmi cədvəllərlə hesablanır.", "ru": "Эквивалент IQ рассчитывается только по официальным таблицам.", "en": "The IQ equivalent is computed only with official tables."}]}, "official": [{"label": {"az": "Vizuallaşdırma/Mühakimə balı", "ru": "Балл визуализации/рассуждения", "en": "Visualization/Reasoning score"}, "hint": {"az": "kompozit", "ru": "композит", "en": "composite"}}, {"label": {"az": "Diqqət/Yaddaş balı", "ru": "Балл внимания/памяти", "en": "Attention/Memory score"}, "hint": {"az": "kompozit", "ru": "композит", "en": "composite"}}, {"label": {"az": "Qeyri-verbal IQ", "ru": "Невербальный IQ", "en": "Nonverbal IQ"}, "hint": {"az": "ümumi bal", "ru": "общий балл", "en": "composite"}}], "domains": [{"id": "d1", "title": {"az": "Fiqur-fon", "ru": "Фигура и фон", "en": "Figure Ground"}, "task": {"az": "Uşağa kartda qarışıq şəkil göstərilir, o, göstərilən fiquru çərçivədə tapıb qoyur. Leiter-3 dəsti lazımdır.", "ru": "Ребёнку показывают карточку со сложным изображением, он находит и вставляет в рамку указанную фигуру. Нужен набор Leiter-3.", "en": "The child is shown a card with a complex picture and finds and places the target figure in the frame. The Leiter-3 kit is needed."}, "items": [{"id": "d1i1", "t": {"az": "Göstərilən fiquru qarışıq fonda tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с поиском указанной фигуры на сложном фоне", "en": "Has difficulty finding the target figure against a complex background"}}, {"id": "d1i2", "t": {"az": "Lazımsız detallara yayınır", "ru": "Отвлекается на ненужные детали", "en": "Is distracted by irrelevant details"}}, {"id": "d1i3", "t": {"az": "Tapşırıq çətinləşəndə axtarışı sistemli aparmır", "ru": "Не ищет систематически, когда задание усложняется", "en": "Does not search systematically when the task becomes harder"}}]}, {"id": "d2", "title": {"az": "Forma tamamlama", "ru": "Завершение формы", "en": "Form Completion"}, "task": {"az": "Uşaq parçalanmış şəkilin hissələrini yerinə qoyub bütövləşdirir.", "ru": "Ребёнок складывает части разрезанного изображения в целое.", "en": "The child puts together the parts of a fragmented picture to make a whole."}, "items": [{"id": "d2i1", "t": {"az": "Hissələri birləşdirib bütöv forma qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с объединением частей в целую форму", "en": "Has difficulty combining parts into a whole form"}}, {"id": "d2i2", "t": {"az": "Natamam formanı tanımaqda çətinlik çəkir", "ru": "Испытывает трудности с узнаванием незавершённой формы", "en": "Has difficulty recognizing an incomplete form"}}, {"id": "d2i3", "t": {"az": "Hissəni qoyarkən çox sınaq-səhv edir", "ru": "Много действует методом проб и ошибок при размещении части", "en": "Relies heavily on trial and error when placing a piece"}}]}, {"id": "d3", "title": {"az": "Təsnifat və analogiya", "ru": "Классификация и аналогии", "en": "Classification and Analogies"}, "task": {"az": "Uşaq kartları oxşarlığına görə qruplara ayırır və «bu nə kimidir, bu da onun kimi» tipli cütləri tamamlayır.", "ru": "Ребёнок группирует карточки по сходству и дополняет пары по принципу «это относится к тому так же, как это к тому».", "en": "The child sorts cards into groups by similarity and completes pairs of the type \"this goes with that as this goes with what?\""}, "items": [{"id": "d3i1", "t": {"az": "Əşyaları qrupa ayırmaqda çətinlik çəkir", "ru": "Испытывает трудности с группировкой предметов", "en": "Has difficulty grouping objects"}}, {"id": "d3i2", "t": {"az": "İki cütün eyni qaydaya uyğun olduğunu görməkdə çətinlik çəkir", "ru": "Испытывает трудности с выявлением того, что две пары подчиняются одному правилу", "en": "Has difficulty seeing that two pairs follow the same rule"}}, {"id": "d3i3", "t": {"az": "Ortaq cəhəti tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с поиском общего признака", "en": "Has difficulty finding the shared feature"}}]}, {"id": "d4", "title": {"az": "Ardıcıl sıralama", "ru": "Последовательный порядок", "en": "Sequential Order"}, "task": {"az": "Uşaq kartları məntiqi sıra ilə düzür və çatışmayan növbəti kartı seçir.", "ru": "Ребёнок раскладывает карточки в логическом порядке и выбирает недостающую следующую карточку.", "en": "The child arranges cards in logical order and selects the missing next card."}, "items": [{"id": "d4i1", "t": {"az": "Kartları məntiqi sıra ilə düzməkdə çətinlik çəkir", "ru": "Испытывает трудности с раскладыванием карточек в логическом порядке", "en": "Has difficulty arranging cards in logical order"}}, {"id": "d4i2", "t": {"az": "Sıranın qaydasını tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с выявлением закономерности последовательности", "en": "Has difficulty finding the rule of the sequence"}}, {"id": "d4i3", "t": {"az": "Növbəti kartı proqnozlaşdırmaqda çətinlik çəkir", "ru": "Испытывает трудности с предсказанием следующей карточки", "en": "Has difficulty predicting the next card"}}]}, {"id": "d5", "title": {"az": "Vizual naxışlar", "ru": "Зрительные паттерны", "en": "Visual Patterns"}, "task": {"az": "Uşaq təkrarlanan naxışın davamını kartlarla qurur.", "ru": "Ребёнок продолжает повторяющийся узор с помощью карточек.", "en": "The child continues a repeating pattern with cards."}, "items": [{"id": "d5i1", "t": {"az": "Naxışın təkrar qaydasını görməkdə çətinlik çəkir", "ru": "Испытывает трудности с выявлением правила повторения узора", "en": "Has difficulty seeing the repeating rule of the pattern"}}, {"id": "d5i2", "t": {"az": "Naxışı doğru davam etdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с правильным продолжением узора", "en": "Has difficulty continuing the pattern correctly"}}, {"id": "d5i3", "t": {"az": "Naxışın bir neçə cəhətini birlikdə nəzərə almaqda çətinlik çəkir", "ru": "Испытывает трудности с одновременным учётом нескольких признаков узора", "en": "Has difficulty attending to several features of the pattern at once"}}]}, {"id": "d6", "title": {"az": "Davamlı diqqət", "ru": "Устойчивое внимание", "en": "Attention Sustained"}, "task": {"az": "Uşaq kartda hədəf şəkilləri vaxt məhdud olduqda cərgələr üzrə işarələyir. Sekundomer lazımdır.", "ru": "Ребёнок отмечает на карточке целевые изображения по рядам с ограничением по времени. Нужен секундомер.", "en": "Within a time limit, the child marks the target pictures row by row on a card. A stopwatch is needed."}, "items": [{"id": "d6i1", "t": {"az": "Tapşırıq boyu diqqətini saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением внимания на протяжении задания", "en": "Has difficulty sustaining attention throughout the task"}}, {"id": "d6i2", "t": {"az": "Hədəfləri ardıcıl seçməkdə çətinlik çəkir", "ru": "Испытывает трудности с последовательным выбором целей", "en": "Has difficulty selecting targets consistently"}}, {"id": "d6i3", "t": {"az": "Ətrafdakı səs və hərəkətlərə yayınır", "ru": "Отвлекается на звуки и движения вокруг", "en": "Is distracted by surrounding sounds and movements"}}]}, {"id": "d7", "title": {"az": "İrəli yaddaş", "ru": "Прямая память", "en": "Forward Memory"}, "task": {"az": "Mütəxəssis şəkillərə sıra ilə toxunur, uşaq eyni sırada təkrarlayır.", "ru": "Специалист по очереди касается картинок, ребёнок повторяет в том же порядке.", "en": "The examiner touches pictures in sequence and the child repeats the sequence in the same order."}, "items": [{"id": "d7i1", "t": {"az": "Şəkillərin sırasını yadda saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с запоминанием порядка картинок", "en": "Has difficulty remembering the order of the pictures"}}, {"id": "d7i2", "t": {"az": "Eyni sırada təkrarlamaqda çətinlik çəkir", "ru": "Испытывает трудности с повторением в том же порядке", "en": "Has difficulty repeating them in the same order"}}, {"id": "d7i3", "t": {"az": "Şəkil sayı artanda sıranı qarışdırır", "ru": "Путает порядок, когда количество картинок увеличивается", "en": "Mixes up the order as the number of pictures increases"}}]}, {"id": "d8", "title": {"az": "Tərs yaddaş", "ru": "Обратная память", "en": "Reverse Memory"}, "task": {"az": "Mütəxəssis şəkillərə sıra ilə toxunur, uşaq tərs sırada təkrarlayır.", "ru": "Специалист по очереди касается картинок, ребёнок повторяет в обратном порядке.", "en": "The examiner touches pictures in sequence and the child repeats the sequence in reverse order."}, "items": [{"id": "d8i1", "t": {"az": "Sıranı tərsinə çevirməkdə çətinlik çəkir", "ru": "Испытывает трудности с обращением порядка", "en": "Has difficulty reversing the order"}}, {"id": "d8i2", "t": {"az": "Məlumatı yadda saxlayıb eyni zamanda dəyişməkdə çətinlik çəkir", "ru": "Испытывает трудности с одновременным удержанием и преобразованием информации", "en": "Has difficulty holding information in mind and transforming it at the same time"}}, {"id": "d8i3", "t": {"az": "Şəkil sayı artanda tapşırığı yarımçıq qoyur", "ru": "Прекращает выполнение задания, когда количество картинок увеличивается", "en": "Abandons the task as the number of pictures increases"}}]}, {"id": "d9", "title": {"az": "Bölünmüş diqqət", "ru": "Распределённое внимание", "en": "Attention Divided"}, "task": {"az": "Uşaq iki tapşırığı eyni vaxtda edir: biri ilə şəkilləri qoyur, digərinə baxıb və ya cavab verir.", "ru": "Ребёнок выполняет два задания одновременно: в одном раскладывает картинки, одновременно следя за другим или отвечая на него.", "en": "The child performs two tasks at the same time: places pictures in one while watching or responding to the other."}, "items": [{"id": "d9i1", "t": {"az": "İki tapşırıq arasında diqqəti bölməkdə çətinlik çəkir", "ru": "Испытывает трудности с распределением внимания между двумя заданиями", "en": "Has difficulty dividing attention between two tasks"}}, {"id": "d9i2", "t": {"az": "Hər iki tapşırıqda sürət və dəqiqliyi saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением скорости и точности в обоих заданиях", "en": "Has difficulty maintaining speed and accuracy on both tasks"}}, {"id": "d9i3", "t": {"az": "Bir tapşırıqdan digərinə keçməkdə çətinlik çəkir", "ru": "Испытывает трудности с переключением с одного задания на другое", "en": "Has difficulty switching from one task to the other"}}]}, {"id": "d10", "title": {"az": "Qeyri-verbal əməkdaşlıq (bütün seansa aid)", "ru": "Невербальное сотрудничество (вся сессия)", "en": "Nonverbal Cooperation (whole session)"}, "task": {"az": "Ayrıca tapşırıq yoxdur. Göstərişlər jest və nümunə ilə verilir, uşağın davranışına baxılır.", "ru": "Отдельного задания нет. Инструкции даются жестами и на примере, наблюдают за поведением ребёнка.", "en": "There is no separate task. Instructions are given by gesture and demonstration, and the child's behavior is observed."}, "items": [{"id": "d10i1", "t": {"az": "Jestlə verilən göstərişi başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием инструкции, данной жестом", "en": "Has difficulty understanding an instruction given by gesture"}}, {"id": "d10i2", "t": {"az": "Tapşırığa davam etməkdə çətinlik çəkir", "ru": "Испытывает трудности с продолжением выполнения задания", "en": "Has difficulty persisting with the task"}}, {"id": "d10i3", "t": {"az": "Çətin tapşırıqda sakitliyini qorumaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением спокойствия при трудном задании", "en": "Has difficulty staying calm on a hard task"}}]}], "specialist": [{"az": "Qeyri-verbal nəticələri dil əsaslı ölçmələrlə müqayisə edin.", "ru": "Сравните невербальные результаты с речевыми измерениями.", "en": "Compare nonverbal results with language-based measures."}, {"az": "Güclü vizual idrakı öyrənmə strategiyasına çevirin.", "ru": "Превратите сильное зрительное мышление в стратегию обучения.", "en": "Translate strong visual reasoning into a learning strategy."}, {"az": "Eşitmə/dil amillərini ayrı-ayrılıqda qiymətləndirməyi tövsiyə edin.", "ru": "Рекомендуйте отдельно оценить слух/речь.", "en": "Recommend separately assessing hearing/language factors."}], "parentIntro": {"az": "Bu test uşağınızın danışmadan da güclü düşünə bildiyini göstərir. Vizual güclü tərəfləri dəstəkləyin.", "ru": "Этот тест показывает, что ребёнок мыслит сильно и без слов. Поддерживайте зрительные сильные стороны.", "en": "This test shows your child can reason strongly without speaking. Support their visual strengths."}, "parentTips": [{"az": "Göstərişləri sözlə yanaşı şəkil və jestlə verin.", "ru": "Давайте инструкции картинками и жестами наряду со словами.", "en": "Give instructions with pictures and gestures alongside words."}, {"az": "Tapmaca, lego və naxış oyunları üçün vaxt ayırın.", "ru": "Выделяйте время на пазлы, лего и узоры.", "en": "Make time for puzzles, building blocks and patterns."}, {"az": "Səbri tərifləyin — düşünmə vaxtı vacibdir.", "ru": "Хвалите терпение — время на размышление важно.", "en": "Praise patience — thinking time matters."}], "games": [{"az": "Naxış davam etdirmə: rəngli bloklarla sıra qurun.", "ru": "Продолжение узора: стройте ряд из цветных блоков.", "en": "Pattern continuation: build a row with colored blocks."}, {"az": "Tapmaca yarışı: çətinliyi tədricən artırın.", "ru": "Гонка пазлов: постепенно увеличивайте сложность.", "en": "Puzzle race: gradually increase difficulty."}, {"az": "'Tap görüm' vizual yaddaş oyunu.", "ru": "Зрительная игра памяти «угадай».", "en": "'Guess what' visual memory game."}]}, "sp2": {"id": "sp2", "name": "Sensory Profile 2", "full": {"az": "Sensor Profil 2", "ru": "Сенсорный профиль 2", "en": "Sensory Profile 2"}, "age": {"az": "Doğuşdan ~14 yaşadək (formalar üzrə)", "ru": "От рождения до ~14 лет (по формам)", "en": "Birth to ~14 years (by form)"}, "summary": {"az": "Uşağın gündəlik həyatda sensor uyaranlara necə reaksiya verdiyini qiymətləndirir. Erqoterapiya və sensor müdaxilə planlaması üçün xüsusilə dəyərlidir.", "ru": "Оценивает, как ребёнок реагирует на сенсорные стимулы в повседневной жизни. Особенно ценен для эрготерапии и сенсорного вмешательства.", "en": "Assesses how the child responds to sensory input in daily life. Especially valuable for occupational therapy and sensory intervention planning."}, "advantages": [{"az": "Sensor müdaxiləni dəqiq hədəfləyir", "ru": "Точно нацеливает сенсорное вмешательство", "en": "Precisely targets sensory intervention"}, {"az": "Gündəlik davranışı sensor baxımdan izah edir", "ru": "Объясняет повседневное поведение через сенсорику", "en": "Explains daily behavior through a sensory lens"}, {"az": "Ev və məktəb mühitinə tövsiyələr verir", "ru": "Даёт рекомендации для дома и школы", "en": "Provides recommendations for home and school"}, {"az": "Valideyn üçün başa düşülən profil yaradır", "ru": "Создаёт понятный родителю профиль", "en": "Creates a parent-friendly profile"}], "instruction": {"howto": [{"az": "Uşağı gündəlik mühitdə müşahidə edən şəxslə doldurun.", "ru": "Заполняйте с тем, кто наблюдает ребёнка в быту.", "en": "Complete with someone who observes the child in daily life."}, {"az": "Hər bənddə davranışın tezliyini qeyd edin.", "ru": "Отмечайте частоту поведения по каждому пункту.", "en": "Record the frequency of the behavior for each item."}, {"az": "Müxtəlif mühitləri (ev, məktəb) nəzərə alın.", "ru": "Учитывайте разные среды (дом, школа).", "en": "Consider different settings (home, school)."}], "methods": [{"az": "Valideyn/müəllim hesabat anketi", "ru": "Анкета-отчёт родителя/учителя", "en": "Parent/teacher report questionnaire"}, {"az": "Tezlik əsaslı qiymətləndirmə", "ru": "Оценка на основе частоты", "en": "Frequency-based rating"}], "scoring": [{"az": "Cavablar dörd sensor kvadrant üzrə yığılır.", "ru": "Ответы сводятся по четырём сенсорным квадрантам.", "en": "Responses aggregate into four sensory quadrants."}, {"az": "Kəsim diapazonları yalnız rəsmi norma ilə müəyyən edilir.", "ru": "Пороговые диапазоны определяются только по официальным нормам.", "en": "Cutoff ranges are determined only by official norms."}]}, "official": [{"label": {"az": "Axtarış (Seeking) balı", "ru": "Балл поиска (Seeking)", "en": "Seeking score"}, "hint": {"az": "rəsmi norma", "ru": "официальная норма", "en": "official norm"}}, {"label": {"az": "Qaçınma (Avoiding) balı", "ru": "Балл избегания (Avoiding)", "en": "Avoiding score"}, "hint": {"az": "rəsmi norma", "ru": "официальная норма", "en": "official norm"}}, {"label": {"az": "Həssaslıq (Sensitivity) balı", "ru": "Балл чувствительности (Sensitivity)", "en": "Sensitivity score"}, "hint": {"az": "rəsmi norma", "ru": "официальная норма", "en": "official norm"}}, {"label": {"az": "Qeydiyyat (Registration) balı", "ru": "Балл регистрации (Registration)", "en": "Registration score"}, "hint": {"az": "rəsmi norma", "ru": "официальная норма", "en": "official norm"}}], "domains": [{"id": "d1", "title": {"az": "Eşitmə emalı", "ru": "Слуховая обработка", "en": "Auditory Processing"}, "task": {"az": "Valideynə sual: uşaq gözlənilməz səslərə (tozsoran, fen, zəng) necə reaksiya verir? Səs-küylü yerdə nə edir?", "ru": "Вопрос родителю: как ребёнок реагирует на неожиданные звуки (пылесос, фен, звонок)? Что он делает в шумном месте?", "en": "Question to the parent: how does the child react to unexpected sounds (vacuum cleaner, hair dryer, bell)? What does the child do in a noisy place?"}, "items": [{"id": "d1i1", "t": {"az": "Gözlənilməz səslərə həddən artıq güclü reaksiya verir (qulaqlarını tutur, ağlayır)", "ru": "Чрезмерно сильно реагирует на неожиданные звуки (закрывает уши, плачет)", "en": "Reacts excessively to unexpected sounds (covers ears, cries)"}}, {"id": "d1i2", "t": {"az": "Səs-küylü yerdə diqqətini toplamaqda çətinlik çəkir", "ru": "Испытывает трудности с концентрацией в шумном месте", "en": "Has difficulty concentrating in a noisy place"}}, {"id": "d1i3", "t": {"az": "Adı çağırılanda və ya səs eşidiləndə reaksiya vermir", "ru": "Не реагирует, когда его зовут по имени или слышен звук", "en": "Does not respond when called by name or when a sound is heard"}}]}, {"id": "d2", "title": {"az": "Görmə emalı", "ru": "Зрительная обработка", "en": "Visual Processing"}, "task": {"az": "Valideynə sual: parlaq işıqda, çox oyuncaq olan otaqda və ya hərəkətli şeylərə baxanda nə olur?", "ru": "Вопрос родителю: что происходит при ярком свете, в комнате с большим количеством игрушек или при взгляде на движущиеся предметы?", "en": "Question to the parent: what happens in bright light, in a room with many toys, or when looking at moving objects?"}, "items": [{"id": "d2i1", "t": {"az": "Parlaq işıqdan narahat olur (gözünü qısır, üzünü çevirir)", "ru": "Яркий свет вызывает дискомфорт (щурится, отворачивается)", "en": "Is bothered by bright light (squints, turns away)"}}, {"id": "d2i2", "t": {"az": "Çox əşya olan yerdə tez yorulur", "ru": "Быстро утомляется там, где много предметов", "en": "Tires quickly in places with many objects"}}, {"id": "d2i3", "t": {"az": "Hərəkətli və ya fırlanan əşyalara həddindən artıq cəlb olunur", "ru": "Чрезмерно притягивается к движущимся или вращающимся предметам", "en": "Is excessively drawn to moving or spinning objects"}}]}, {"id": "d3", "title": {"az": "Toxunma emalı", "ru": "Тактильная обработка", "en": "Touch Processing"}, "task": {"az": "Valideynə sual: paltarın etiketinə, saç yuyulmasına, ayaqyalın gəzməyə və qucaqlanmağa necə reaksiya verir?", "ru": "Вопрос родителю: как ребёнок реагирует на бирки на одежде, мытьё головы, хождение босиком, объятия?", "en": "Question to the parent: how does the child react to clothing labels, hair washing, walking barefoot, and hugs?"}, "items": [{"id": "d3i1", "t": {"az": "Müəyyən parçalardan və ya toxunuşdan narahat olur", "ru": "Испытывает дискомфорт от определённых тканей или прикосновений", "en": "Is bothered by certain fabrics or touch"}}, {"id": "d3i2", "t": {"az": "Güclü sıxılma və ya təzyiq axtarır", "ru": "Ищет сильное сжатие или давление", "en": "Seeks strong squeezing or pressure"}}, {"id": "d3i3", "t": {"az": "Əlləri və ya ağzı ilə hər şeyə toxunmağa meyl edir", "ru": "Склонен трогать всё руками или ртом", "en": "Tends to touch everything with hands or mouth"}}]}, {"id": "d4", "title": {"az": "Hərəkət emalı", "ru": "Обработка движения", "en": "Movement Processing"}, "task": {"az": "Valideynə sual: yellənçək, fırlanma, təpədən sürüşmə kimi oyunlara münasibəti necədir?", "ru": "Вопрос родителю: как ребёнок относится к качелям, кружению, скольжению с горки?", "en": "Question to the parent: how does the child respond to swings, spinning, and sliding down a slide?"}, "items": [{"id": "d4i1", "t": {"az": "Fırlanma, yellənmə kimi hərəkətləri çox axtarır", "ru": "Активно ищет кружение, раскачивание и подобные движения", "en": "Strongly seeks spinning, swinging, and similar movements"}}, {"id": "d4i2", "t": {"az": "Hərəkətli oyunlarda ehtiyatlı və ya qorxaqdır", "ru": "Осторожен или боязлив в подвижных играх", "en": "Is cautious or fearful in active play"}}, {"id": "d4i3", "t": {"az": "Tarazlığı saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением равновесия", "en": "Has difficulty keeping balance"}}]}, {"id": "d5", "title": {"az": "Bədən mövqeyi", "ru": "Положение тела", "en": "Body Position"}, "task": {"az": "Valideynə sual: uşaq əşyalara və adamlara çırpılır? Qapını çırpır, əşyanı sındırır? Oturanda və yeriyəndə bədənini necə saxlayır?", "ru": "Вопрос родителю: сталкивается ли ребёнок с предметами и людьми? Хлопает ли дверью, ломает ли вещи? Как держит тело, когда сидит и ходит?", "en": "Question to the parent: does the child bump into objects and people? Does the child slam doors or break things? How does the child hold his or her body when sitting and walking?"}, "items": [{"id": "d5i1", "t": {"az": "Bədən mövqeyini az hiss edir (tez-tez yıxılır, əşyalara dəyir)", "ru": "Слабо ощущает положение тела (часто падает, задевает предметы)", "en": "Has a poor sense of body position (falls often, bumps into things)"}}, {"id": "d5i2", "t": {"az": "Əşyalara və adamlara çırpılır", "ru": "Сталкивается с предметами и людьми", "en": "Bumps into objects and people"}}, {"id": "d5i3", "t": {"az": "Gücünü tənzimləməkdə çətinlik çəkir (çox möhkəm tutur, çox bərk vurur)", "ru": "Испытывает трудности с регуляцией силы (слишком крепко держит, слишком сильно бьёт)", "en": "Has difficulty regulating force (grips too tightly, hits too hard)"}}]}, {"id": "d6", "title": {"az": "Oral (dad və qoxu)", "ru": "Оральная обработка (вкус и запах)", "en": "Oral Sensory Processing (taste and smell)"}, "task": {"az": "Valideynə sual: yeni yeməklərə, yeməyin teksturasına və qoxulara necə reaksiya verir?", "ru": "Вопрос родителю: как ребёнок реагирует на новую еду, текстуру пищи и запахи?", "en": "Question to the parent: how does the child respond to new foods, food textures, and smells?"}, "items": [{"id": "d6i1", "t": {"az": "Yeni dadlardan və qoxulardan imtina edir", "ru": "Отказывается от новых вкусов и запахов", "en": "Refuses new tastes and smells"}}, {"id": "d6i2", "t": {"az": "Müəyyən teksturadan (yumşaq, lopa) imtina edir", "ru": "Отказывается от определённых текстур (мягкие, комковатые)", "en": "Refuses certain textures (soft, lumpy)"}}, {"id": "d6i3", "t": {"az": "Yeyilməyən əşyaları ağzına aparır", "ru": "Берёт в рот несъедобные предметы", "en": "Puts inedible objects in the mouth"}}]}, {"id": "d7", "title": {"az": "Davranış reaksiyaları", "ru": "Поведенческие реакции", "en": "Behavioral Responses"}, "task": {"az": "Valideynə sual: səs-küylü, izdihamlı və ya yeni yerdə uşağın davranışı necə dəyişir?", "ru": "Вопрос родителю: как меняется поведение ребёнка в шумном, людном или новом месте?", "en": "Question to the parent: how does the child's behavior change in a noisy, crowded, or new place?"}, "items": [{"id": "d7i1", "t": {"az": "Sensor yük artanda davranışı pozulur", "ru": "Поведение нарушается при возрастании сенсорной нагрузки", "en": "Behavior breaks down when sensory load increases"}}, {"id": "d7i2", "t": {"az": "Bir fəaliyyətdən digərinə keçməkdə çətinlik çəkir", "ru": "Испытывает трудности с переходом от одной деятельности к другой", "en": "Has difficulty moving from one activity to another"}}, {"id": "d7i3", "t": {"az": "Mühit dəyişəndə narahat olur", "ru": "Тревожится при смене обстановки", "en": "Becomes distressed when the environment changes"}}]}, {"id": "d8", "title": {"az": "Sosial-emosional", "ru": "Социально-эмоциональная сфера", "en": "Social-Emotional Responses"}, "task": {"az": "Valideynə sual: sensor narahatlıq olanda əhval-ruhiyyəsi dəyişir? Özünü sakitləşdirə bilir?", "ru": "Вопрос родителю: меняется ли настроение ребёнка при сенсорном дискомфорте? Умеет ли он успокаиваться сам?", "en": "Question to the parent: does the child's mood change with sensory discomfort? Can the child calm himself or herself?"}, "items": [{"id": "d8i1", "t": {"az": "Sensor narahatlıq əhvalına təsir edir", "ru": "Сенсорный дискомфорт влияет на настроение", "en": "Sensory discomfort affects mood"}}, {"id": "d8i2", "t": {"az": "Özünü sakitləşdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с самоуспокоением", "en": "Has difficulty calming himself or herself"}}, {"id": "d8i3", "t": {"az": "Ya diqqət axtarır, ya da başqalarından uzaqlaşır", "ru": "Либо ищет внимания, либо отдаляется от других", "en": "Either seeks attention or withdraws from others"}}]}, {"id": "d9", "title": {"az": "Diqqət", "ru": "Внимание", "en": "Attention"}, "task": {"az": "Valideynə sual: dərs, oyun və ya yemək zamanı diqqəti dağılır? Yerində otura bilir?", "ru": "Вопрос родителю: рассеивается ли внимание ребёнка во время занятия, игры или еды? Может ли он усидеть на месте?", "en": "Question to the parent: is the child's attention scattered during lessons, play, or meals? Can the child stay seated?"}, "items": [{"id": "d9i1", "t": {"az": "Diqqəti asanlıqla yayınır", "ru": "Внимание легко отвлекается", "en": "Is easily distracted"}}, {"id": "d9i2", "t": {"az": "Tapşırığa diqqəti saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с удержанием внимания на задании", "en": "Has difficulty sustaining attention on a task"}}, {"id": "d9i3", "t": {"az": "Diqqətini saxlamaq üçün hərəkət edir", "ru": "Двигается, чтобы удерживать внимание", "en": "Moves in order to keep attention"}}]}, {"id": "d10", "title": {"az": "Axtarış kvadrantı", "ru": "Квадрант «поиск»", "en": "Seeking Quadrant"}, "task": {"az": "Valideynə sual: uşaq əlavə hərəkət, səs və ya toxunuş axtarır? Daim hərəkətdədir?", "ru": "Вопрос родителю: ищет ли ребёнок дополнительного движения, звука или прикосновения? Постоянно ли он в движении?", "en": "Question to the parent: does the child look for extra movement, sound, or touch? Is the child constantly on the move?"}, "items": [{"id": "d10i1", "t": {"az": "Əlavə sensor təsir axtarır", "ru": "Ищет дополнительные сенсорные впечатления", "en": "Seeks additional sensory input"}}, {"id": "d10i2", "t": {"az": "Daim hərəkətdə və fəaldır", "ru": "Постоянно в движении и активен", "en": "Is constantly moving and active"}}, {"id": "d10i3", "t": {"az": "Səs, toxunuş və ya hərəkətdən çox həzz alır", "ru": "Получает чрезмерное удовольствие от звука, прикосновения или движения", "en": "Takes great pleasure in sound, touch, or movement"}}]}, {"id": "d11", "title": {"az": "Qaçınma kvadrantı", "ru": "Квадрант «избегание»", "en": "Avoiding Quadrant"}, "task": {"az": "Valideynə sual: güclü səs, izdiham və gözlənilməz hadisələrdən uzaq durur? Tanış mühiti üstün tutur?", "ru": "Вопрос родителю: избегает ли ребёнок громких звуков, толпы, неожиданных событий? Предпочитает ли знакомую обстановку?", "en": "Question to the parent: does the child avoid loud sounds, crowds, and unexpected events? Does the child prefer a familiar environment?"}, "items": [{"id": "d11i1", "t": {"az": "Güclü təsirlərdən uzaqlaşır", "ru": "Отстраняется от сильных воздействий", "en": "Withdraws from strong sensory input"}}, {"id": "d11i2", "t": {"az": "İzdihamlı yerlərdən qaçır", "ru": "Избегает людных мест", "en": "Avoids crowded places"}}, {"id": "d11i3", "t": {"az": "Tanış və proqnozlaşdırıla bilən mühit tələb edir", "ru": "Требует знакомой и предсказуемой обстановки", "en": "Needs a familiar and predictable environment"}}]}, {"id": "d12", "title": {"az": "Həssaslıq kvadrantı", "ru": "Квадрант «чувствительность»", "en": "Sensitivity Quadrant"}, "task": {"az": "Valideynə sual: kiçik səs və ya dəyişikliyi başqalarından tez hiss edir? Tez yüklənir?", "ru": "Вопрос родителю: замечает ли ребёнок небольшой звук или изменение раньше других? Быстро ли перегружается?", "en": "Question to the parent: does the child notice a small sound or change sooner than others? Does the child become overloaded quickly?"}, "items": [{"id": "d12i1", "t": {"az": "Təsirlərə həddindən artıq reaksiya verir", "ru": "Чрезмерно реагирует на воздействия", "en": "Overreacts to sensory input"}}, {"id": "d12i2", "t": {"az": "Kiçik dəyişiklikləri tez hiss edir", "ru": "Быстро замечает небольшие изменения", "en": "Quickly notices small changes"}}, {"id": "d12i3", "t": {"az": "Tez yüklənir və sakitləşməkdə çətinlik çəkir", "ru": "Быстро перегружается и с трудом успокаивается", "en": "Becomes overloaded quickly and has difficulty calming down"}}]}, {"id": "d13", "title": {"az": "Qeydiyyat kvadrantı", "ru": "Квадрант «регистрация»", "en": "Registration Quadrant"}, "task": {"az": "Valideynə sual: uşaq səs, toxunuş və ya ağrını gec hiss edir? Bəzən «öz dünyasında» olur?", "ru": "Вопрос родителю: поздно ли ребёнок замечает звук, прикосновение или боль? Бывает ли, что он «в своём мире»?", "en": "Question to the parent: is the child slow to notice sound, touch, or pain? Does the child sometimes seem to be \"in his or her own world\"?"}, "items": [{"id": "d13i1", "t": {"az": "Təsirləri gec fərq edir", "ru": "Поздно замечает воздействия", "en": "Is slow to notice sensory input"}}, {"id": "d13i2", "t": {"az": "Ağrını və ya temperaturu az hiss edir", "ru": "Слабо ощущает боль или температуру", "en": "Has a poor sense of pain or temperature"}}, {"id": "d13i3", "t": {"az": "Enerjisi aşağıdır və ya «öz dünyasında» görünür", "ru": "Низкий уровень энергии или выглядит «в своём мире»", "en": "Has low energy or appears to be \"in his or her own world\""}}]}], "specialist": [{"az": "Hər kvadrantı uşağın konkret gündəlik davranışı ilə bağlayın.", "ru": "Свяжите каждый квадрант с конкретным повседневным поведением.", "en": "Link each quadrant to the child's concrete daily behavior."}, {"az": "Ev və sinif üçün 'sensor pəhriz' tövsiyələri hazırlayın.", "ru": "Подготовьте рекомендации «сенсорной диеты» для дома и класса.", "en": "Prepare 'sensory diet' recommendations for home and classroom."}, {"az": "Erqoterapevtlə birgə müdaxilə planı qurun.", "ru": "Постройте план вмешательства совместно с эрготерапевтом.", "en": "Build the intervention plan together with an occupational therapist."}], "parentIntro": {"az": "Uşağınızın 'çətin' görünən davranışları çox vaxt sensor ehtiyacdır. Mühiti uyğunlaşdırmaq çox kömək edir.", "ru": "«Трудное» поведение ребёнка часто — сенсорная потребность. Адаптация среды очень помогает.", "en": "Your child's 'difficult' behaviors are often a sensory need. Adapting the environment helps a lot."}, "parentTips": [{"az": "Həssaslıq varsa: səs-küyü azaldın, sakit künc yaradın.", "ru": "При чувствительности: снижайте шум, создайте тихий уголок.", "en": "If sensitive: reduce noise, create a quiet corner."}, {"az": "Axtarış varsa: təhlükəsiz hərəkət və sıxılma imkanı verin.", "ru": "При поиске: дайте безопасное движение и сжатие.", "en": "If seeking: provide safe movement and deep-pressure input."}, {"az": "Keçidləri əvvəlcədən xəbər verin ki, sürpriz olmasın.", "ru": "Предупреждайте о переходах заранее, чтобы не было сюрприза.", "en": "Announce transitions in advance so they aren't a surprise."}], "games": [{"az": "Sensor qutu: düyü, lobya, qum içində əşya axtarmaq.", "ru": "Сенсорная коробка: поиск предметов в рисе, фасоли, песке.", "en": "Sensory bin: find objects in rice, beans or sand."}, {"az": "Yastıq 'sendviçi': yumşaq təzyiq sakitləşdirir.", "ru": "«Бутерброд» из подушек: мягкое давление успокаивает.", "en": "Pillow 'sandwich': gentle pressure soothes."}, {"az": "Maneə yolu: tarazlıq və bədən fərqindəliyi üçün.", "ru": "Полоса препятствий: для баланса и осознания тела.", "en": "Obstacle course: for balance and body awareness."}]}}};